(function(A){Object.assign(A.D,{"G2962":{"l":"κύριος","o":717,"ar":"<f><o>κύριος</o>، <g>-α, -ον</g> (وأيضًا <g>-ος, -ον</g>)،</f> <s><b>ذو سلطان</b> (<g>κῦρος</g>) أو <b>ذو سيادة</b>؛ اسمًا، <g>ὁ κ.</g>، <b>رب</b>، <b>سيد</b>؛ <s n=\"1.\">بوجه عام: مع المضاف إليه للشيء، <r v=\"Matt.9.38\"></r> <r v=\"Matt.20.8\"></r>، <r v=\"Mark.12.9\"></r> <r v=\"Mark.13.35\"></r>، <r v=\"Luke.19.33\"></r>؛ <g>τ. σαββάτου</g>، <r v=\"Matt.12.8\"></r>، <r v=\"Mark.2.28\"></r>، <r v=\"Luke.6.5\"></r>؛ مع المضاف إليه للشخص، <g>δούλου</g>، إلخ، <r v=\"Matt.10.24\"></r>، <r v=\"Luke.14.21\"></r>، <r v=\"Acts.16.16\"></r>، وفي مواضع أخرى؛ مطلقًا، عكس <g>οἱ δοῦλοι</g>، <r v=\"Eph.6.5\"></r>، <r v=\"Eph.6.9\"></r>، وفي مواضع أخرى؛ عن الإمبراطور، <r v=\"Acts.25.26\"></r>؛ <g>θεοὶ πολλοὶ καὶ κ. πολλοί</g>، <r v=\"1Cor.8.5\"></r>؛ عن الزوج، <r v=\"1Pet.3.6\"></r>؛ في النداء، لقبَ احترام للسادة والمعلمين والحكام ونحوهم، <r v=\"Matt.13.27\"></r> <r v=\"Matt.16.22\"></r> <r v=\"Matt.27.63\"></r>، <r v=\"Mark.7.28\"></r>، <r v=\"Luke.5.12\"></r>، <r v=\"John.4.11\"></r>، <r v=\"Acts.9.5\"></r>، وفي مواضع أخرى.</s> <s n=\"2.\">لقبًا إلهيًّا؛ في العهد الجديد، <s n=\"(a)\">عن الله: <g>ὁ κ.</g>، <r v=\"Matt.5.33\"></r>، <r v=\"Mark.5.19\"></r>، <r v=\"Luke.1.6\"></r>، <r v=\"Acts.7.33\"></r>، <r v=\"Heb.8.2\"></r>، <r v=\"Jas.4.15\"></r>، وفي مواضع أخرى؛ بدون أداة التعريف، <r v=\"Matt.21.9\"></r>، <r v=\"Mark.13.20\"></r>، <r v=\"Luke.1.17\"></r>، <r v=\"Heb.7.21\"></r>، <r v=\"1Pet.1.25\"></r>، وفي مواضع أخرى؛ <g>κ. τ. οὐρανοῦ καὶ τ. γῆς</g>، <r v=\"Matt.11.25\"></r>؛ <g>τ. κυριευόντων</g>، <r v=\"1Tim.6.15\"></r>؛ <g>κ. ὁ θεός</g>، <r v=\"Matt.4.7\"></r>، <r v=\"Matt.4.10\"></r> وفي مواضع أخرى؛ والتعبير نفسه يليه <g>ὁ παντοκράτωρ</g>، <r v=\"Rev.4.8\"></r>؛ <g>κ. σαβαώθ</g>، <r v=\"Rom.9.29\"></r>؛ (<g>ὁ</g>) <g>ἄγγελος κυρίου</g>، <r v=\"Matt.1.20\"></r> <r v=\"Matt.2.13\"></r>، <r v=\"Luke.1.11\"></r>، وفي مواضع أخرى؛ <g>πνεῦμα κυρίου</g>، <r v=\"Luke.4.18\"></r>، <r v=\"Acts.8.39\"></r>؛</s> <s n=\"(b)\">عن المسيح: <r v=\"Matt.21.3\"></r>، <r v=\"Mark.11.3\"></r>، <r v=\"Luke.1.43\"></r> <r v=\"Luke.20.44\"></r>، وفي مواضع أخرى؛ عن يسوع بعد قيامته، <r v=\"Acts.10.36\"></r>، <r v=\"Rom.14.8\"></r>، <r v=\"1Cor.7.22\"></r>، <r v=\"Eph.4.5\"></r>، وفي مواضع أخرى؛ <g>ὁ κ. μου</g>، <r v=\"John.20.28\"></r>؛ <g>ὁ κ. Ἰησοῦς</g>، <r v=\"Acts.1.21\"></r>، <r v=\"1Cor.11.23\"></r>، وفي مواضع أخرى؛ والتعبير نفسه يليه <g>Χριστός</g>، <r v=\"Eph.1.2\"></r>، وفي مواضع أخرى؛ <g>ὁ κ. ἡμῶν</g>، <r v=\"1Tim.1.14\"></r>، <r v=\"Heb.7.14\"></r>، وفي مواضع أخرى؛ والتعبير نفسه يليه <g>Ἰησοῦς</g>، <r v=\"1Thess.3.11\"></r>، <r v=\"Heb.13.20\"></r>، وفي مواضع أخرى؛ <g>Χριστός</g>، <r v=\"Rom.16.18\"></r>؛ <g>Ἰ Χ.</g>، <r v=\"1Cor.1.2\"></r>، <r v=\"1Thess.1.3\"></r>، وفي مواضع أخرى؛ <g>Ἰ. Χ.</g> (<g>Χ. Ἰ</g>) <g>ὁ κ.</g> (<g>ἡμῶν</g>)، <r v=\"Rom.1.4\"></r>، <r v=\"Col.2.6\"></r>، <r v=\"Eph.3.11\"></r>، وفي مواضع أخرى؛ <g>ὁ κ. καὶ ὁ σωτὴρ</g>، <r v=\"2Pet.3.2\"></r>؛ والتعبير نفسه يليه <g>Ἰ. Χ.</g>، <r v=\"2Pet.3.18\"></r>؛ بدون أداة التعريف، <r v=\"1Cor.7.22\"></r>، <r v=\"1Cor.7.25\"></r>، <r v=\"Jas.5.4\"></r>، وفي مواضع أخرى؛ <g>κ. κυρίων</g>، <r v=\"Rev.19.16\"></r>؛ مع حرف جر، <g>ἀπὸ</g> (<g>κατὰ</g>، <g>πρὸς</g>، <g>σὺν</g>، إلخ) <g>κ.</g>، <r v=\"Col.3.24\"></r>، وفي مواضع أخرى.</s> </s> </s>","en":"<f><o>κύριος</o>, <g>-α, -ον</g> (also <g>-ος, -ον</g>),</f> <et> <e t=\"septuagint\">[in LXX (subst.) chiefly for <h n=\"H3069\">יהוה</h>, also for <h n=\"H113\">אָדוֹן</h>, <h n=\"H1167\">בַּעַל</h>, etc.;]</e> </et> <s><b>having power</b> (<g>κῦρος</g>) or <b>authority</b>; as subst., <g>ὁ κ.</g>, <b>lord</b>, <b>master</b>; <s n=\"1.\">in general: c. gen. rei, <r v=\"Matt.9.38\"></r> <r v=\"Matt.20.8\"></r>, <r v=\"Mark.12.9\"></r> <r v=\"Mark.13.35\"></r>, <r v=\"Luke.19.33\"></r>; <g>τ. σαββάτου</g>, <r v=\"Matt.12.8\"></r>, <r v=\"Mark.2.28\"></r>, <r v=\"Luke.6.5\"></r>; c. gen. pers., <g>δούλου</g>, etc., <r v=\"Matt.10.24\"></r>, <r v=\"Luke.14.21\"></r>, <r v=\"Acts.16.16\"></r>, al.; absol., opp. to <g>οἱ δοῦλοι</g>, <r v=\"Eph.6.5\"></r>, <r v=\"Eph.6.9\"></r>, al.; of the Emperor (Deiss., <i>LAE</i>, 161), <r v=\"Acts.25.26\"></r>; <g>θεοὶ πολλοὶ καὶ κ. πολλοί</g>, <r v=\"1Cor.8.5\"></r>; of a husband, <r v=\"1Pet.3.6\"></r>; in voc., as a title of respect to masters, teachers, magistrates, etc., <r v=\"Matt.13.27\"></r> <r v=\"Matt.16.22\"></r> <r v=\"Matt.27.63\"></r>, <r v=\"Mark.7.28\"></r>, <r v=\"Luke.5.12\"></r>, <r v=\"John.4.11\"></r>, <r v=\"Acts.9.5\"></r>, al.</s> <s n=\"2.\">As a divine title (freq. in <g>π.</g>; Deiss., <i>LAE</i>, 353 ff.); in NT, <s n=\"(a)\">of God: <g>ὁ κ.</g>, <r v=\"Matt.5.33\"></r>, <r v=\"Mark.5.19\"></r>, <r v=\"Luke.1.6\"></r>, <r v=\"Acts.7.33\"></r>, <r v=\"Heb.8.2\"></r>, <r v=\"Jas.4.15\"></r>, al.; anarth. (Bl., § 46, 6), <r v=\"Matt.21.9\"></r>, <r v=\"Mark.13.20\"></r>, <r v=\"Luke.1.17\"></r>, <r v=\"Heb.7.21\"></r>, <r v=\"1Pet.1.25\"></r>, al.; <g>κ. τ. οὐρανοῦ καὶ τ. γῆς</g>, <r v=\"Matt.11.25\"></r>; <g>τ. κυριευόντων</g>, <r v=\"1Tim.6.15\"></r>; <g>κ. ὁ θεός</g>, <r v=\"Matt.4.7\"></r>, <r v=\"Matt.4.10\"></r> al.; id. seq. <g>ὁ παντοκράτωρ</g>, <r v=\"Rev.4.8\"></r>; <g>κ. σαβαώθ</g>, <r v=\"Rom.9.29\"></r>; (<g>ὁ</g>) <g>ἄγγελος κυρίου</g>, <r v=\"Matt.1.20\"></r> <r v=\"Matt.2.13\"></r>, <r v=\"Luke.1.11\"></r>, al.; <g>πνεῦμα κυρίου</g>, <r v=\"Luke.4.18\"></r>, <r v=\"Acts.8.39\"></r>;</s> <s n=\"(b)\">of the Christ: <r v=\"Matt.21.3\"></r>, <r v=\"Mark.11.3\"></r>, <r v=\"Luke.1.43\"></r> <r v=\"Luke.20.44\"></r>, al.; of Jesus after his resurrection (Dalman, <i>Words</i>, 330), <r v=\"Acts.10.36\"></r>, <r v=\"Rom.14.8\"></r>, <r v=\"1Cor.7.22\"></r>, <r v=\"Eph.4.5\"></r>, al.; <g>ὁ κ. μου</g>, <r v=\"John.20.28\"></r>; <g>ὁ κ. Ἰησοῦς</g>, <r v=\"Acts.1.21\"></r>, <r v=\"1Cor.11.23\"></r>, al.; id. seq. <g>Χριστός</g>, <r v=\"Eph.1.2\"></r>, al.; <g>ὁ κ. ἡμῶν</g>, <r v=\"1Tim.1.14\"></r>, <r v=\"Heb.7.14\"></r>, al.; id. seq. <g>Ἰησοῦς</g>, <r v=\"1Thess.3.11\"></r>, <r v=\"Heb.13.20\"></r>, al.; <g>Χριστός</g>, <r v=\"Rom.16.18\"></r>; <g>Ἰ Χ.</g>, <r v=\"1Cor.1.2\"></r>, <r v=\"1Thess.1.3\"></r>, al.; <g>Ἰ. Χ.</g> (<g>Χ. Ἰ</g>) <g>ὁ κ.</g> (<g>ἡμῶν</g>), <r v=\"Rom.1.4\"></r>, <r v=\"Col.2.6\"></r>, <r v=\"Eph.3.11\"></r>, al.; <g>ὁ κ. καὶ ὁ σωτὴρ</g>, <r v=\"2Pet.3.2\"></r>; id. seq. <g>Ἰ. Χ.</g>, <r v=\"2Pet.3.18\"></r>; anarth., <r v=\"1Cor.7.22\"></r>, <r v=\"1Cor.7.25\"></r>, <r v=\"Jas.5.4\"></r>, al.; <g>κ. κυρίων</g>, <r v=\"Rev.19.16\"></r>; c. prep., <g>ἀπὸ</g> (<g>κατὰ</g>, <g>πρὸς</g>, <g>σὺν</g>, etc.) <g>κ.</g>, <r v=\"Col.3.24\"></r>, al.</s> </s> </s> <sy><i>SYN:</i> v.s. <g>δεσπότης</g>.</sy>"},"G2936":{"l":"κτίζω","o":15,"ar":"<f><o>κτίζω</o>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>يُعمِّر (بالسكان)</b> أو <b>يؤسِّس</b> إقليمًا أو مدينة (<r v=\"1Esd.4.53\"></r>).</s> <s n=\"2.\">في السبعينية والعهد الجديد، عن الله، <b>يخلق</b>: <r v=\"Mark.13.19\"></r>، <r v=\"1Cor.11.9\"></r>، <r v=\"Col.1.16\"></r> <r v=\"Col.3.10\"></r>، <r v=\"Eph.3.9\"></r>، <r v=\"1Tim.4.3\"></r>، <r v=\"Rev.4.11\"></r> <r v=\"Rev.10.6\"></r>؛ <g>ὁ κτίσας</g>، <r v=\"Matt.19.4\"></r>، <r v=\"Rom.1.25\"></r>؛ عن العمل الإلهي في النفس، <r v=\"Eph.2.10\"></r>، <r v=\"Eph.2.15\"></r> <r v=\"Eph.4.24\"></r> (قارن <r v=\"Ps.51.10\"></r>).†</s>","en":"<f><o>κτίζω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1254\">בּרא</h>, <r v=\"Ps.51.10\"></r>, al.; also for <h n=\"H7069\">קנה</h>, <r v=\"Gen.14.19\"></r>, <r v=\"Prov.8.22\"></r>; <h n=\"H3335\">יצר</h>, <r v=\"Isa.22.11\"></r> <r v=\"Isa.46.11\"></r>, <r v=\"Wis.2.23\"></r>, <r v=\"Sir.1.4\"></r>, <r v=\"Sir.1.9\"></r> (and freq.), <r v=\"1Esd.4.53\"></r>, a1.;]</e> </et> <s n=\"1.\">in cl., <b>to people</b> or <b>found</b> a region or city (<r v=\"1Esd.4.53\"></r>).</s> <s n=\"2.\">In LXX and NT, of God, <b>to create</b>: <r v=\"Mark.13.19\"></r>, <r v=\"1Cor.11.9\"></r>, <r v=\"Col.1.16\"></r> <r v=\"Col.3.10\"></r>, <r v=\"Eph.3.9\"></r>, <r v=\"1Tim.4.3\"></r>, <r v=\"Rev.4.11\"></r> <r v=\"Rev.10.6\"></r>; <g>ὁ κτίσας</g>, <r v=\"Matt.19.4\"></r> (WH, R, mg.), <r v=\"Rom.1.25\"></r>; of the divine operation on the soul, <r v=\"Eph.2.10\"></r>, <r v=\"Eph.2.15\"></r> <r v=\"Eph.4.24\"></r> (cf. <r v=\"Ps.51.10\"></r>).†</s>"},"G2963":{"l":"κυριότης","o":4,"ar":"<f>*† <o>κυριότης</o>، <g>-ητος, ἡ</g></f> <s><b>سيادة</b>، <b>رياسة (سلطان)</b>: <r v=\"Eph.1.21\"></r>، <r v=\"2Pet.2.10\"></r>، <r v=\"Jude.1.8\"></r>؛ جمع، <r v=\"Col.1.16\"></r> (قارن <r v=\"Col.1.16\"></r>، <r v=\"Jude.1.8\"></r>).†</s>","en":"<f>*† <o>κυριότης</o>, <g>-ητος, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>κύριος</g>),</e> </et> <s><b>lordship</b>, <b>dominion</b>: <r v=\"Eph.1.21\"></r>, <r v=\"2Pet.2.10\"></r>, <r v=\"Jude.1.8\"></r>; pl., <r v=\"Col.1.16\"></r> (cf. Lft., <r v=\"Col.1.16\"></r>; Mayor, <r v=\"Jude.1.8\"></r>; <i>DB</i>, i, 616 f.).†</s>"},"G2901":{"l":"κραταιόω","o":4,"ar":"<f>† <o>κραταιόω</o>، <g>-ῶ</g></f> <s><b>يُقوِّي</b>؛ المبني للمجهول، <b>يتقوّى</b>: <r v=\"Luke.2.40\"></r>، <r v=\"1Cor.16.13\"></r>؛ <g>πνεύματι</g>، <r v=\"Luke.1.80\"></r>؛ <g>δυνάμει κ. διὰ τ. πνεύματος</g>، <r v=\"Eph.3.16\"></r>.†</s>","en":"<f>† <o>κραταιόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(late form of <g>κρατύνω</g>; &lt; <g>κράτος</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2388\">חזק</h>;]</e> </et> <s><b>to strengthen</b>; pass., <b>to wax strong</b>: <r v=\"Luke.2.40\"></r>, <r v=\"1Cor.16.13\"></r>; <g>πνεύματι</g>, <r v=\"Luke.1.80\"></r>; <g>δυνάμει κ. διὰ τ. πνεύματος</g>, <r v=\"Eph.3.16\"></r>.†</s>"},"G2980":{"l":"λαλέω","o":296,"ar":"<f><o>λαλέω</o>، <g>-ῶ</g>،</f> <s> <s n=\"1.\"><b>يُصدر صوتًا (ينطق)</b>: عن الجمادات، <r v=\"Rev.4.1\"></r> <r v=\"Rev.10.4\"></r>؛ مجازيًا، <r v=\"Heb.11.4\"></r> <r v=\"Heb.12.24\"></r>.</s> <s n=\"2.\"><b>يتحدّث</b>، <b>يتكلّم</b>، <b>يقول</b>: مطلقًا، <r v=\"Matt.9.33\"></r> <r v=\"Matt.12.46\"></r>، <r v=\"Mark.5.35\"></r>، <r v=\"Luke.8.49\"></r>؛ «يليه» <g>ὡς</g>، <r v=\"1Cor.13.11\"></r>، <r v=\"Rev.13.11\"></r>؛ <g>εἰς</g>، <r v=\"1Cor.14.9\"></r>؛ <g>ἐκ</g>، <r v=\"Matt.12.34\"></r>؛ مع منصوب الشيء، <r v=\"Matt.10.19\"></r>، <r v=\"Mark.11.32\"></r>، <r v=\"John.8.30\"></r>، وفي مواضع أخرى؛ مع قابل الشخص، <r v=\"Matt.12.46\"></r>، <r v=\"Luke.24.6\"></r>، <r v=\"Rom.7.1\"></r>، وفي مواضع أخرى؛ مع منصوب الشيء وقابل الشخص، <r v=\"Matt.9.18\"></r>، <r v=\"John.10.6\"></r>، وفي مواضع أخرى؛ مع حرف جر، <g>πρός</g>، <g>μετά</g>، <g>περί</g>، <r v=\"Mark.6.50\"></r>، <r v=\"Luke.1.19\"></r> <r v=\"Luke.2.33\"></r>، وفي مواضع أخرى؛ <g>ἐν</g>، <g>ἐξ</g>، <g>ἀπό</g>، <r v=\"Matt.13.3\"></r>، <r v=\"John.12.49\"></r> <r v=\"John.14.10\"></r>، وفي مواضع أخرى؛ <g>λ. τ. λόγον</g>، <r v=\"Mark.8.32\"></r>، وفي مواضع أخرى؛ «يليه» كلام مباشر، <r v=\"Mark.14.31\"></r>، <r v=\"Heb.5.5\"></r> <r v=\"Heb.11.18\"></r>؛ وعلى الأسلوب العبري، <g>ἐλάλησε λέγων</g>، <r v=\"Matt.14.27\"></r>، <r v=\"John.8.12\"></r>، <r v=\"Acts.8.26\"></r>، وفي مواضع أخرى.</s> </s>","en":"<f><o>λαλέω</o>, <g>-ῶ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1696\">דּבר</h> pi., also for <h n=\"H559\">אמר</h>, etc.;]</e> </et> <s> <s n=\"1.\"><b>to utter</b>: of inanimate things, <r v=\"Rev.4.1\"></r> <r v=\"Rev.10.4\"></r>; metaph., <r v=\"Heb.11.4\"></r> <r v=\"Heb.12.24\"></r>.</s> <s n=\"2.\"><b>to talk</b>, <b>speak</b>, <b>say</b>: absol., <r v=\"Matt.9.33\"></r> <r v=\"Matt.12.46\"></r>, <r v=\"Mark.5.35\"></r>, <r v=\"Luke.8.49\"></r>; seq. <g>ὡς</g>, <r v=\"1Cor.13.11\"></r>, <r v=\"Rev.13.11\"></r>; <g>εἰς</g>, <r v=\"1Cor.14.9\"></r>; <g>ἐκ</g>, <r v=\"Matt.12.34\"></r>; c. acc. rei, <r v=\"Matt.10.19\"></r>, <r v=\"Mark.11.32\"></r>, <r v=\"John.8.30\"></r>, al.; c. dat. pers., <r v=\"Matt.12.46\"></r>, <r v=\"Luke.24.6\"></r>, <r v=\"Rom.7.1\"></r>, al.; c. acc. rei et dat. pers., <r v=\"Matt.9.18\"></r>, <r v=\"John.10.6\"></r>, al.; c. prep., <g>πρός</g>, <g>μετά</g>, <g>περί</g>, <r v=\"Mark.6.50\"></r>, <r v=\"Luke.1.19\"></r> <r v=\"Luke.2.33\"></r>, al.; <g>ἐν</g>, <g>ἐξ</g>, <g>ἀπό</g>, <r v=\"Matt.13.3\"></r>, <r v=\"John.12.49\"></r> <r v=\"John.14.10\"></r>, al.; <g>λ. τ. λόγον</g>, <r v=\"Mark.8.32\"></r>, al.; seq. orat. dir. (not cl.), <r v=\"Mark.14.31\"></r>, <r v=\"Heb.5.5\"></r> <r v=\"Heb.11.18\"></r>; Hebraistically (Dalman, <i>Words</i>, 25 f.), <g>ἐλάλησε λέγων</g>, <r v=\"Matt.14.27\"></r>, <r v=\"John.8.12\"></r>, <r v=\"Acts.8.26\"></r>, al.</s> </s> <sy><i>SYN.</i>: v.s. <g>λέγω</g>.</sy>"},"G2904":{"l":"κράτος","o":12,"ar":"<f><o>κράτος</o>، <g>-εος</g> (<g>-ους</g>)، <g>τό</g>،</f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>قوّة</b>، خاصةً القوة الجسدية.</s> <s n=\"2.\"><b>قدرة</b>، <b>شدّة</b>: <r v=\"Heb.2.14\"></r>؛ <g>τὸ κ. τῆς ἰσχύος αὐτοῦ</g>، <r v=\"Eph.1.19\"></r> <r v=\"Eph.6.10\"></r> (<r v=\"Isa.40.26\"></r>، <r v=\"Dan.4.27\"></r>)؛ <g>τ. δόςης αὐτοῦ</g>، <r v=\"Col.1.11\"></r>؛ <g>κατὰ κράτος</g>، <b>بشدّة (بقوة)</b>، <r v=\"Acts.19.20\"></r>؛ <b>عمل قدير</b>، <b>عمل قوة</b>، <r v=\"Luke.1.51\"></r>؛ في التمجيدات، <r v=\"1Tim.6.16\"></r>، <r v=\"1Pet.4.11\"></r> <r v=\"1Pet.5.11\"></r>، <r v=\"Jude.1.25\"></r>، <r v=\"Rev.1.6\"></r> <r v=\"Rev.5.13\"></r>.†</s>","en":"<f><o>κράτος</o>, <g>-εος</g> (<g>-ους</g>), <g>τό</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5797\">עֹז</h>, <r v=\"Job.12.16\"></r>, <r v=\"Ps.90.11\"></r> al.;]</e> </et> <s n=\"1.\"><b>strength</b>, esp. as in Hom., of bodily strength.</s> <s n=\"2.\"><b>power</b>, <b>might</b>: <r v=\"Heb.2.14\"></r>; <g>τὸ κ. τῆς ἰσχύος αὐτοῦ</g>, <r v=\"Eph.1.19\"></r> <r v=\"Eph.6.10\"></r> (<r v=\"Isa.40.26\"></r>, <r v=\"Dan.4.27\"></r>); <g>τ. δόςης αὐτοῦ</g>, <r v=\"Col.1.11\"></r>; <g>κατὰ κράτος</g>, <b>mightily</b>, <r v=\"Acts.19.20\"></r>; <b>a mighty deed</b>, <b>an act of power</b>, <r v=\"Luke.1.51\"></r>; in doxologies, <r v=\"1Tim.6.16\"></r>, <r v=\"1Pet.4.11\"></r> <r v=\"1Pet.5.11\"></r>, <r v=\"Jude.1.25\"></r>, <r v=\"Rev.1.6\"></r> <r v=\"Rev.5.13\"></r>.†</s>"},"G2940":{"l":"κυβία","o":1,"ar":"<f>* <o>κυβία</o> (في الأتيكية <g>-εία</g>)، <g>-ας, ἡ</g></f> <s><b>لعب النرد</b>؛ مجازيًا، <b>خداع</b>، <b>حيلة (خفّة يد)</b>: <r v=\"Eph.4.14\"></r>.†</s>","en":"<f>* <o>κυβία</o> (Att. <g>-εία</g>, and so Rec.), <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>κύβος</g>, <i>a cube</i>, <i>a die</i>),</e> </et> <s><b>dice-playing</b>; metaph., <b>trickery</b>, <b>sleight</b>: <r v=\"Eph.4.14\"></r>.†</s>"},"G2906":{"l":"κραυγή","o":6,"ar":"<f><o>κραυγή</o>، <g>-ῆς, ἡ</g>،</f> <s><b>صراخ</b>، <b>صيحة</b>، <b>ضجيج</b>: <r v=\"Matt.25.6\"></r>، <r v=\"Luke.1.42\"></r>، <r v=\"Acts.23.9\"></r>، <r v=\"Eph.4.31\"></r>، <r v=\"Heb.5.7\"></r>، <r v=\"Rev.21.4\"></r>.†</s>","en":"<f><o>κραυγή</o>, <g>-ῆς, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H6818\">צְעָקָה</h>, <h n=\"H8643\">תְּרוּעָה</h>, <h n=\"H7775\">שַׁוְעָה</h>, etc.;]</e> </et> <s><b>crying</b>, <b>outcry</b>, <b>clamour</b>: <r v=\"Matt.25.6\"></r>, <r v=\"Luke.1.42\"></r>, <r v=\"Acts.23.9\"></r>, <r v=\"Eph.4.31\"></r>, <r v=\"Heb.5.7\"></r>, <r v=\"Rev.21.4\"></r>.†</s>"},"G2931":{"l":"κρυφῇ","o":1,"ar":"<f><o>κρυφῇ</o></f> ظرف، <s><b>سرًّا</b>، <b>في الخفاء</b>: <r v=\"Eph.5.12\"></r>.†</s>","en":"<f><o>κρυφῇ</o></f> <et> <e t=\"derivation\">(prop. <g>-ῆ</g>, Rec.; later spelling is due to assimilation to dat.; cf. <g>εἰκῆ</g>),</e> </et> adv., <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5641\">סתר</h>;]</e> </et> <s><b>secretly</b>, <b>in secret</b>: <r v=\"Eph.5.12\"></r>.†</s>"},"G2917":{"l":"κρίμα","o":27,"ar":"<f><o>κρίμα</o>، <g>-τος, τό</g></f> <s>نتيجة إجراء قضائي، ومن ثَمَّ، <s n=\"1.\"><b>دينونة، حكم</b>، القرار الصادر في أخطاء الآخرين: <r v=\"Matt.7.2\"></r>؛ بالمعنى القضائي، مع المضاف إليه للعقوبة، <r v=\"Luke.24.20\"></r>؛ خاصةً عن دينونة الله، <r v=\"Rom.2.2\"></r> <r v=\"Rom.5.16\"></r> <r v=\"Rom.11.33\"></r>، <r v=\"2Pet.2.3\"></r>، <r v=\"Jude.1.4\"></r>؛ <g>κ. λαμβάι εσθαι</g>، <r v=\"Matt.23.13\"></r>، <r v=\"Mark.12.40\"></r>، <r v=\"Luke.20.47\"></r>، <r v=\"Rom.13.2\"></r>، <r v=\"Jas.3.1\"></r>؛ <g>ἔχειν</g>، <r v=\"1Tim.5.12\"></r>؛ <g>βαστάζειν</g>، <r v=\"Gal.5.10\"></r>؛ <g>ἐσθίειν ἑαυτῷ</g>، <r v=\"1Cor.11.29\"></r>؛ <g>εἰς κ. συνέρχεσθαι</g>، <r v=\"1Cor.11.34\"></r>؛ <g>εἶναι ἐν τ αὐτῷ κ.</g>، <r v=\"Luke.23.40\"></r>؛ مع المضاف إليه للمفعول، <r v=\"Rom.3.8\"></r>، <r v=\"1Tim.3.6\"></r>، <r v=\"Rev.17.1\"></r>؛ عن دينونة الله بالمسيح، <r v=\"John.9.39\"></r>؛ <g>τὸ κ. ἄρχεται</g>، <r v=\"1Pet.4.17\"></r>؛ <g>τ. κ. τ. μέλλον</g>، <r v=\"Acts.24.25\"></r>؛ <g>κ. αἰώνιον</g>، <r v=\"Heb.6.2\"></r>؛ <g>ἔκρινεν ὁ Θεὸς τ. κ. ὐμῶν</g>، <r v=\"Rev.18.20\"></r>؛ عن حق الدينونة، <r v=\"Rev.20.4\"></r>.</s> <s n=\"2.\"><b>قضية</b> للحكم فيها، <b>دعوى</b>، <b>محاكمة</b>: <r v=\"1Cor.6.7\"></r>.†</s> </s>","en":"<f><o>κρίμα</o> (Bl., § 27, 2), <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>κρίνω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4941\">מִשְׁפָּט</h>;]</e> </et> <s>the issue of a judicial process, hence, <s n=\"1.\"><b>judgment</b>, the decision passed on the faults of others: <r v=\"Matt.7.2\"></r>; in forensic sense, c. gen. pun., <r v=\"Luke.24.20\"></r>; esp. of the judgment of God, <r v=\"Rom.2.2\"></r> <r v=\"Rom.5.16\"></r> <r v=\"Rom.11.33\"></r> (<i>ICC</i>, in l.), <r v=\"2Pet.2.3\"></r>, <r v=\"Jude.1.4\"></r>; <g>κ. λαμβάι εσθαι</g>, <r v=\"Matt.23.13\"></r> (Rec., R, mg.), <r v=\"Mark.12.40\"></r>, <r v=\"Luke.20.47\"></r>, <r v=\"Rom.13.2\"></r>, <r v=\"Jas.3.1\"></r>; <g>ἔχειν</g>, <r v=\"1Tim.5.12\"></r>; <g>βαστάζειν</g>, <r v=\"Gal.5.10\"></r>; <g>ἐσθίειν ἑαυτῷ</g>, <r v=\"1Cor.11.29\"></r>; <g>εἰς κ. συνέρχεσθαι</g>, <r v=\"1Cor.11.34\"></r>; <g>εἶναι ἐν τ αὐτῷ κ.</g>, <r v=\"Luke.23.40\"></r>; c. gen. obj., <r v=\"Rom.3.8\"></r>, <r v=\"1Tim.3.6\"></r>, <r v=\"Rev.17.1\"></r>; of God's judgment through Christ, <r v=\"John.9.39\"></r>; <g>τὸ κ. ἄρχεται</g>, <r v=\"1Pet.4.17\"></r>; <g>τ. κ. τ. μέλλον</g>, <r v=\"Acts.24.25\"></r>; <g>κ. αἰώνιον</g>, <r v=\"Heb.6.2\"></r>; <g>ἔκρινεν ὁ Θεὸς τ. κ. ὐμῶν</g>, <r v=\"Rev.18.20\"></r>; of the right of judgment, <r v=\"Rev.20.4\"></r>.</s> <s n=\"2.\"><b>a matter</b> for judgment, <b>a law-suit</b>, <b>a case</b>: <r v=\"1Cor.6.7\"></r>.†</s> </s>"},"G2993":{"l":"Λαοδικία","o":6,"ar":"<f><o>Λαοδικία</o>، <g>-ας, ἡ</g>،</f> <s><b>لاودكية</b>، مدينة على نهر ليكوس في فريجية: <r v=\"Col.2.1\"></r> <r v=\"Col.4.13\"></r>، <r v=\"Col.4.15\"></r>، <r v=\"Col.4.16\"></r>، <r v=\"Rev.1.11\"></r> <r v=\"Rev.3.14\"></r>.†</s>","en":"<f><o>Λαοδικία</o> (Rec. <g>-εία</g>), <g>-ας, ἡ</g>,</f> <s><b>Laodicea</b>, a city on the Lycus in Phrygia: <r v=\"Col.2.1\"></r> <r v=\"Col.4.13\"></r>, <r v=\"Col.4.15\"></r>, <r v=\"Col.4.16\"></r>, <r v=\"Rev.1.11\"></r> <r v=\"Rev.3.14\"></r>.†</s>"},"G2914":{"l":"Κρήτη","o":5,"ar":"<f><o>Κρήτη</o>، <g>-ης, ἡ</g>،</f> <s><b>كريت</b>: <r v=\"Acts.27.7\"></r>، <r v=\"Acts.27.12\"></r>، <r v=\"Acts.27.12\"></r>، <r v=\"Acts.27.31\"></r>، <r v=\"Titus.1.5\"></r>.†</s>","en":"<f><o>Κρήτη</o>, <g>-ης, ἡ</g>,</f> <s><b>Crete</b>: <r v=\"Acts.27.7\"></r>, <r v=\"Acts.27.12\"></r>, <r v=\"Acts.27.12\"></r>, <r v=\"Acts.27.31\"></r>, <r v=\"Titus.1.5\"></r>.†</s>"},"G2912":{"l":"Κρής","o":2,"ar":"<f><o>Κρής</o>، <g>ὁ</g>، الجمع، <g>Κρῆτες</g>،</f> <s><b>كريتي</b>: <r v=\"Acts.2.11\"></r>، <r v=\"Titus.1.12\"></r>.†</s>","en":"<f><o>Κρής</o>, <g>ὁ</g>, pl., <g>Κρῆτες</g>,</f> <s><b>a Cretan</b>: <r v=\"Acts.2.11\"></r>, <r v=\"Titus.1.12\"></r>.†</s>"},"G2928":{"l":"κρύπτω","o":18,"ar":"<f><o>κρύπτω</o>،</f> <s><b>يُخفي</b>، <b>يكتم</b>: مع المنصوب، <r v=\"Matt.13.44\"></r>، <r v=\"Matt.25.18\"></r>؛ يليه <g>ἐν</g>، <r v=\"Matt.25.25\"></r> (المبني للمجهول، <r v=\"Matt.13.44\"></r>، <r v=\"Col.3.3\"></r>)؛ المبني للمجهول، <r v=\"Matt.5.14\"></r>، <r v=\"Heb.11.23\"></r>، <r v=\"1Tim.5.25\"></r>، <r v=\"Rev.2.17\"></r>؛ <g>ἐκρύβη</g> <g>κ. ἐξῆλθεν</g>، <r v=\"John.8.59\"></r>؛ يليه <g>εἰς</g>، <r v=\"Luke.13.21\"></r>، <r v=\"Rev.6.15\"></r>؛ <g>ἀπό</g>، <r v=\"Rev.6.16\"></r>؛ المبني للمجهول، <r v=\"John.12.36\"></r>. مجازيًا: <r v=\"Matt.11.25\"></r>، <r v=\"Matt.13.35\"></r>، <r v=\"Luke.11.52\"></r>، <r v=\"Luke.18.34\"></r>، <r v=\"Luke.19.42\"></r>، <r v=\"John.19.38\"></r> (قارن <g>ἀτο-</g>، <g>ἐν-</g>، <g>περι-κρύπτω</g>).†</s>","en":"<f><o>κρύπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H2244\">חבא</h>, <h n=\"H2934\">טמן</h>, <h n=\"H5641\">סתר</h>, <h n=\"H6845\">צפן</h>, etc.;]</e> </et> <s><b>to hide</b>, <b>conceal</b>: c. acc., <r v=\"Matt.13.44\"></r> <r v=\"Matt.25.18\"></r>; seq. <g>ἐν</g>, <r v=\"Matt.25.25\"></r> (pass., <r v=\"Matt.13.44\"></r>, <r v=\"Col.3.3\"></r>); pass., <r v=\"Matt.5.14\"></r>, <r v=\"Heb.11.23\"></r>, <r v=\"1Tim.5.25\"></r>, <r v=\"Rev.2.17\"></r>; <g>ἐκρύβη</g> (on the tense and its formation, v. M, <i>Pr.</i>, 161; Bl., § 19, 3) <g>κ. ἐξῆλθεν</g>, <r v=\"John.8.59\"></r>; seq. <g>εἰς</g>, <r v=\"Luke.13.21\"></r>, <r v=\"Rev.6.15\"></r>; <g>ἀπό</g> (in cl. more freq. dupl. acc.), <r v=\"Rev.6.16\"></r>; pass., <r v=\"John.12.36\"></r>, (Bl., § 34, 4). Metaph.: <r v=\"Matt.11.25\"></r> <r v=\"Matt.13.35\"></r>, <r v=\"Luke.11.52\"></r>, WH, mg., <r v=\"Luke.18.34\"></r> <r v=\"Luke.19.42\"></r>, <r v=\"John.19.38\"></r> (cf. <g>ἀτο-</g>, <g>ἐν-</g>, <g>περι-κρύπτω</g>).†</s>"},"G2938":{"l":"κτίσμα","o":4,"ar":"<f>** <o>κτίσμα</o>، <g>-τος, τό</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>مستعمرة</b>.</s> <s n=\"2.\"><b>شيء مخلوق</b>، <b>خليقة</b>: <r v=\"1Tim.4.4\"></r>، <r v=\"Jas.1.18\"></r>، <r v=\"Rev.5.13\"></r>، <r v=\"Rev.8.9\"></r>.†</s>","en":"<f>** <o>κτίσμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>κτίζω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Wis.9.2\"></r> <r v=\"Wis.13.5\"></r> <r v=\"Wis.14.11\"></r>, <r v=\"Sir.36.20\"></r> (<r v=\"Sir.36.17\"></r>), <r v=\"Sir.38.34\"></r>, <r v=\"3Macc.5.11\"></r>*;]</e> </et> <s n=\"1.\">(cl.) <b>a colony</b>.</s> <s n=\"2.\"><b>a created thing</b>, <b>creature</b>: <r v=\"1Tim.4.4\"></r>, <r v=\"Jas.1.18\"></r>, <r v=\"Rev.5.13\"></r> <r v=\"Rev.8.9\"></r>.†</s>"},"G2965":{"l":"κύων","o":5,"ar":"<f><o>κύων, κυνός</o>، <g>ὁ, ἡ</g></f> <s><b>كلب</b>: <r v=\"Luke.16.21\"></r>، <r v=\"2Pet.2.22\"></r>؛ مجازيًا، كلمة تعيير، <r v=\"Matt.7.6\"></r>، <r v=\"Phil.3.2\"></r>، <r v=\"Rev.22.15\"></r>.†</s>","en":"<f><o>κύων, κυνός</o>, <g>ὁ, ἡ</g></f> <et> (in NT masc. only), <e t=\"septuagint\">[in LXX for<h n=\"H3611\">כֶּלֶב</h>;]</e> </et> <s><b>a dog</b>: <r v=\"Luke.16.21\"></r>, <r v=\"2Pet.2.22\"></r>; metaph., as a word of reproach, <r v=\"Matt.7.6\"></r>, <r v=\"Phil.3.2\"></r>, <r v=\"Rev.22.15\"></r>.†</s>"},"G2913":{"l":"Κρήσκης","o":1,"ar":"<f><o>Κρήσκης</o>، <g>-εντος</g>، <g>ὁ</g> (اسم لاتيني)،</f> <s><b>كريسكيس</b>: <r v=\"2Tim.4.10\"></r>.†</s>","en":"<f><o>Κρήσκης</o>, <g>-εντος</g> (Bl., § 10, 4), <g>ὁ</g> (Lat.),</f> <s><b>Crescens</b>: <r v=\"2Tim.4.10\"></r>.†</s>"},"G2967":{"l":"κωλύω","o":23,"ar":"<f><o>κωλύω</o></f> <s><b>عاق</b>، <b>منع</b>، <b>نهى</b>، <b>حجب</b>: مع المنصوب والمصدر: <r v=\"Matt.19.14\"></r>، <r v=\"Luke.23.2\"></r>، <r v=\"Acts.8.36\"></r>، <r v=\"Acts.16.6\"></r>، <r v=\"Acts.24.23\"></r>، <r v=\"1Thess.2.16\"></r>، <r v=\"Heb.7.23\"></r>؛ مع حذف المصدر: <r v=\"Mark.9.38\"></r>، <r v=\"Mark.9.39\"></r>، <r v=\"Mark.10.14\"></r>، <r v=\"Luke.9.49\"></r>، <r v=\"Luke.9.50\"></r>، <r v=\"Luke.11.52\"></r>، <r v=\"Luke.18.16\"></r>، <r v=\"Acts.11.17\"></r>، <r v=\"Rom.1.13\"></r>، <r v=\"3John.1.10\"></r>؛ مع حذف المنصوب: <r v=\"1Tim.4.3\"></r>؛ مع منصوب الشخص ومضاف إليه الشيء: <r v=\"Acts.27.43\"></r>؛ مع منصوب الشيء: <r v=\"1Cor.14.39\"></r>، <r v=\"2Pet.2.16\"></r>؛ وكذلك يليه <g>τοῦ μή</g>: <r v=\"Acts.10.47\"></r>؛ وكذلك يليه <g>ἀπό</g> (مثل العبرية <h n=\"H3607\">כָּלָא</h> <h n=\"H4480\">מִן</h>، <r v=\"Gen.23.6\"></r>، وفي مواضع أخرى): <r v=\"Luke.6.29\"></r> (قارن <g>δια-κωλύω</g>).†</s>","en":"<f><o>κωλύω</o></f> <et> <e t=\"derivation\">(&lt; <g>κόλος</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H3607\">כּלא</h>, <h n=\"H4513\">מנע</h>, etc.;]</e> </et> <s><b>to hinder</b>, <b>restrain</b>, <b>forbid</b>, <b>withhold</b>: c. acc. et inf., <r v=\"Matt.19.14\"></r>, <r v=\"Luke.23.2\"></r>, <r v=\"Acts.8.36\"></r> <r v=\"Acts.16.6\"></r> <r v=\"Acts.24.23\"></r>, <r v=\"1Thess.2.16\"></r>, <r v=\"Heb.7.23\"></r>; inf. om., <r v=\"Mark.9.38\"></r>, <r v=\"Mark.9.39\"></r> <r v=\"Mark.10.14\"></r>, <r v=\"Luke.9.49\"></r>, <r v=\"Luke.9.50\"></r> <r v=\"Luke.11.52\"></r> <r v=\"Luke.18.16\"></r>, <r v=\"Acts.11.17\"></r>, <r v=\"Rom.1.13\"></r>, <r v=\"3John.1.10\"></r>; acc. om., <r v=\"1Tim.4.3\"></r>; c. acc. pers. et gen. rei, <r v=\"Acts.27.43\"></r>; c. acc. rei, <r v=\"1Cor.14.39\"></r>, <r v=\"2Pet.2.16\"></r>; id. seq. <g>τοῦ μή</g>, <r v=\"Acts.10.47\"></r>; id. seq. <g>ἀπό</g> (like Heb. <h n=\"H3607\">כָּלָא</h> <h n=\"H4480\">מִן</h>, <r v=\"Gen.23.6\"></r>, al.), <r v=\"Luke.6.29\"></r> (cf. <g>δια-κωλύω</g>).†</s>"},"G2945":{"l":"κύκλος","o":8,"ar":"<f><o>κύκλος</o>، <g>-ου, ὁ</g>،</f> <s><b>حلقة</b>، <b>دائرة</b>. حالة القابل <g>κύκλῳ</g> ظرفًا: <b>حول، حواليه</b>، <b>من حول</b>: <r v=\"Mark.3.34\"></r>، <r v=\"Mark.6.6\"></r>، <r v=\"Mark.6.36\"></r>، <r v=\"Luke.9.12\"></r>، <r v=\"Rom.15.19\"></r>؛ مع المضاف إليه: <r v=\"Rev.4.6\"></r>، <r v=\"Rev.5.11\"></r>، <r v=\"Rev.7.11\"></r>.†</s>","en":"<f><o>κύκλος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5439\">סָבִיב</h>;]</e> </et> <s><b>a ring</b>, <b>circle</b>. Dat., <g>κύκλῳ</g>, as adverb., <b>round about</b>, <b>around</b>: <r v=\"Mark.3.34\"></r> <r v=\"Mark.6.6\"></r>, <r v=\"Mark.6.36\"></r>, <r v=\"Luke.9.12\"></r>, <r v=\"Rom.15.19\"></r>; c. gen., <r v=\"Rev.4.6\"></r> <r v=\"Rev.5.11\"></r> <r v=\"Rev.7.11\"></r>.†</s>"},"G2919":{"l":"κρίνω","o":114,"ar":"<f><o>κρίνω</o>،</f> <s> <s n=\"1.\"><b>فَصَلَ</b>، <b>انتقى</b>، <b>اختار</b> (في اليونانية الكلاسيكية؛ وفي السبعينية: <r v=\"2Macc.13.15\"></r>).</s> <s n=\"2.\"><b>استحسن</b>، <b>اعتبر</b>: <r v=\"Rom.14.5\"></r>.</s> <s n=\"3.\"><b>رأى، ارتأى</b>، <b>حكم</b>، <b>ظنّ</b>: <r v=\"Luke.7.43\"></r>، <r v=\"1Cor.11.13\"></r>؛ يليه <g>τοῦτο ὅτι</g>، <r v=\"2Cor.5.14\"></r>؛ مع المنصوب والمصدر، <r v=\"Acts.16.15\"></r>؛ مع المنصوب والخبر، <r v=\"Acts.13.46\"></r> <r v=\"Acts.26.8\"></r>.</s> <s n=\"4.\"><b>قرّر</b>، <b>عزم</b>، <b>قضى</b>: مع المنصوب، <r v=\"Acts.16.4\"></r>، <r v=\"Rom.14.13\"></r>، <r v=\"1Cor.7.37\"></r>، <r v=\"2Cor.2.1\"></r>؛ مع المصدر، <r v=\"Acts.20.16\"></r> <r v=\"Acts.25.25\"></r>، <r v=\"1Cor.2.2\"></r> <r v=\"1Cor.5.3\"></r>، <r v=\"Titus.3.12\"></r> (قارن <r v=\"1Macc.11.33\"></r>، <r v=\"Wis.8.9\"></r>، وفي مواضع أخرى)؛ مع المنصوب والمصدر، <r v=\"Acts.21.25\"></r> <r v=\"Acts.27.1\"></r>.</s> <s n=\"5.\"><b>دان، حكم</b>، <b>قضى</b>، <b>أصدر حكمًا</b>: مطلقًا، <r v=\"John.8.16\"></r>، <r v=\"John.8.26\"></r>؛ يليه <g>κατά</g> مع المنصوب، <r v=\"John.7.24\"></r> <r v=\"John.8.15\"></r>؛ <g>κρίσιν κ.</g>، <r v=\"John.7.24\"></r>؛ <g>τ. δίκαιον</g>، <r v=\"Luke.12.57\"></r>؛ بالمعنى القضائي، <r v=\"John.18.31\"></r>، <r v=\"Acts.23.3\"></r>، وفي مواضع أخرى؛ المبني للمجهول، <r v=\"Rom.3.4\"></r>؛ عن دينونة الله، <r v=\"John.5.30\"></r> <r v=\"John.8.50\"></r>، <r v=\"Rom.2.16\"></r> <r v=\"Rom.3.6\"></r>، <r v=\"2Tim.4.1\"></r>، <r v=\"1Pet.4.5\"></r>، وفي مواضع أخرى.</s> <s n=\"6.\">= <g>κατακρίνω</g>، <b>دان، حكم بالإدانة</b>: <r v=\"Acts.13.27\"></r>؛ عن دينونة الله، <r v=\"John.3.18\"></r> <r v=\"John.5.22\"></r> <r v=\"John.12.47\"></r>، <r v=\"John.12.48\"></r>، <r v=\"Acts.7.7\"></r>، <r v=\"Rom.2.12\"></r>، <r v=\"1Cor.11.32\"></r>، <r v=\"Heb.10.30\"></r><i>(السبعينية)</i>، <r v=\"Jas.5.9\"></r>، <r v=\"Rev.19.2\"></r>، وفي مواضع أخرى.</s> <s n=\"7.\">كما في السبعينية (ترجمةً لـ <h n=\"H8199\">שׁפט</h>)، <b>حكم، تولّى الحكم</b>، <b>ساس</b> (<r v=\"2Kgs.15.5\"></r>، <r v=\"Ps.2.10\"></r>، وفي مواضع أخرى): <r v=\"Matt.19.28\"></r>، <r v=\"Luke.22.30\"></r>، <r v=\"1Cor.6.3\"></r>.</s> <s n=\"8.\"><b>قدّم إلى المحاكمة</b>؛ الصيغة الوسطى: <b>تقاضى، رفع دعوى</b>: مع القابل للشخص، <r v=\"Matt.5.40\"></r>؛ يليه <g>μετά</g> مع المضاف إليه للشخص (الخصم)، و<g>ἐπί</g> مع المضاف إليه (القاضي)، <r v=\"1Cor.6.1\"></r>، <r v=\"1Cor.6.6\"></r> (قارن <g>ἀνα-</g>، <g>ἀπο-</g>، <g>ἀντ-απο-</g> (<g>-μαι</g>)، <g>δια-</g>، <g>ἐν-</g>، <g>ἐπι-</g>، <g>κατα-</g>، <g>συν-</g>، <g>ὑπο-</g> (<g>-μαι</g>)، <g>συν-υπο-</g> (<g>-μαι</g>)).</s> </s>","en":"<f><o>κρίνω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8199\">שׁפט</h>, also for <h n=\"H1777\">דּין</h>, <h n=\"H7378\">ריב</h>, etc.;]</e> </et> <s> <s n=\"1.\"><b>to</b> <b>separate</b>, <b>select</b>, <b>choose</b> (cl.; in LXX: <r v=\"2Macc.13.15\"></r>).</s> <s n=\"2.\"><b>to approve</b>, <b>esteem</b>: <r v=\"Rom.14.5\"></r>.</s> <s n=\"3.\"><b>to be of opinion</b>, <b>judge</b>, <b>think</b>: <r v=\"Luke.7.43\"></r>, <r v=\"1Cor.11.13\"></r>; seq. <g>τοῦτο ὅτι</g>, <r v=\"2Cor.5.14\"></r>; c. acc. et inf., <r v=\"Acts.16.15\"></r>; c. acc. et pred., <r v=\"Acts.13.46\"></r> <r v=\"Acts.26.8\"></r>.</s> <s n=\"4.\"><b>to decide</b>, <b>determine</b>, <b>decree</b>: c. acc., <r v=\"Acts.16.4\"></r>, <r v=\"Rom.14.13\"></r>, <r v=\"1Cor.7.37\"></r>, <r v=\"2Cor.2.1\"></r>; c. inf. (Field, <i>Notes</i>, 167), <r v=\"Acts.20.16\"></r> <r v=\"Acts.25.25\"></r>, <r v=\"1Cor.2.2\"></r> <r v=\"1Cor.5.3\"></r>, <r v=\"Titus.3.12\"></r> (cf. <r v=\"1Macc.11.33\"></r>, <r v=\"Wis.8.9\"></r>, al.); c. acc. et inf., <r v=\"Acts.21.25\"></r> <r v=\"Acts.27.1\"></r>.</s> <s n=\"5.\"><b>to judge</b>, <b>adjudge</b>, <b>pronounce judgment</b>: absol., <r v=\"John.8.16\"></r>, <r v=\"John.8.26\"></r>; seq. <g>κατά</g>, c. acc., <r v=\"John.7.24\"></r> <r v=\"John.8.15\"></r>; <g>κρίσιν κ.</g>, <r v=\"John.7.24\"></r>; <g>τ. δίκαιον</g>, <r v=\"Luke.12.57\"></r> (Deiss., <i>LAE</i>, 118); in forensic sense, <r v=\"John.18.31\"></r>, <r v=\"Acts.23.3\"></r>, al.; pass., <r v=\"Rom.3.4\"></r><i>(LXX)</i>; of God's judgment, <r v=\"John.5.30\"></r> <r v=\"John.8.50\"></r>, <r v=\"Rom.2.16\"></r> <r v=\"Rom.3.6\"></r>, <r v=\"2Tim.4.1\"></r>, <r v=\"1Pet.4.5\"></r>, al.</s> <s n=\"6.\">= <g>κατακρίνω</g>, <b>to condemn</b> (cl.): <r v=\"Acts.13.27\"></r>; of God's judgment, <r v=\"John.3.18\"></r> <r v=\"John.5.22\"></r> <r v=\"John.12.47\"></r>, <r v=\"John.12.48\"></r>, <r v=\"Acts.7.7\"></r>, <r v=\"Rom.2.12\"></r>, <r v=\"1Cor.11.32\"></r>, <r v=\"Heb.10.30\"></r><i>(LXX)</i>, <r v=\"Jas.5.9\"></r>, <r v=\"Rev.19.2\"></r>, al.</s> <s n=\"7.\">As in LXX (for <h n=\"H8199\">שׁפט</h>), <b>to rule</b>, <b>govern</b> (<r v=\"2Kgs.15.5\"></r>, <r v=\"Ps.2.10\"></r>, al.): <r v=\"Matt.19.28\"></r>, <r v=\"Luke.22.30\"></r>, <r v=\"1Cor.6.3\"></r>.</s> <s n=\"8.\"><b>to bring to trial</b> (cl.); mid., <b>to go to law</b>: c. dat. pers., <r v=\"Matt.5.40\"></r>; seq. <g>μετά</g>, c. gen. pers. (of the opponent), <g>ἐπί</g>, c. gen. (of the judge), <r v=\"1Cor.6.1\"></r>, <r v=\"1Cor.6.6\"></r> (cf. <g>ἀνα-</g>, <g>ἀπο-</g>, <g>ἀντ-απο-</g> (<g>-μαι</g>), <g>δια-</g>, <g>ἐν-</g>, <g>ἐπι-</g>, <g>κατα-</g>, <g>συν-</g>, <g>ὑπο-</g> (<g>-μαι</g>), <g>συν-υπο-</g> (<g>-μαι</g>)).</s> </s> <sy><i>SYN.</i>: v.s. <g>δικάστης</g>.</sy>"},"G2999":{"l":"λατρεία","o":5,"ar":"<f><o>λατρεία</o>، <g>-ας, ἡ</g></f> <s n=\"1.\"><b>خدمة مأجورة</b>، <b>خدمة</b>.</s> <s n=\"2.\"><b>خدمة</b> إلهية، <b>عبادة</b>: <r v=\"John.16.2\"></r>، <r v=\"Rom.9.4\"></r> <r v=\"Rom.12.1\"></r>، <r v=\"Heb.9.1\"></r>، <r v=\"Heb.9.6\"></r>.†</s>","en":"<f><o>λατρεία</o>, <g>-ας, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>λατρεύω</g>, q.v.),</e> <e t=\"septuagint\">[in LXX (always of divine service): <r v=\"Exod.12.25\"></r>, <r v=\"Exod.12.26\"></r> <r v=\"Exod.13.5\"></r>, <r v=\"Josh.22.27\"></r>, <r v=\"1Chr.28.13\"></r> (<h n=\"H5656\">עֲבֹדָה</h>), <r v=\"1Macc.1.43\"></r> <r v=\"1Macc.2.19\"></r>, <r v=\"1Macc.2.22\"></r>, <r v=\"3Macc.4.14\"></r>*;]</e> </et> <s n=\"1.\"><b>hired service</b>, <b>service</b>.</s> <s n=\"2.\">(in cl. also) divine <b>service</b>, <b>worship</b>: <r v=\"John.16.2\"></r>, <r v=\"Rom.9.4\"></r> <r v=\"Rom.12.1\"></r>, <r v=\"Heb.9.1\"></r>, <r v=\"Heb.9.6\"></r>.†</s>"},"G2964":{"l":"κυρόω","o":2,"ar":"<f><o>κυρόω</o>، <g>-ῶ</g></f> <s><b>ثبّت</b>، <b>صدّق، أقرّ</b>، <b>جعله نافذًا</b>: <r v=\"2Cor.2.8\"></r>؛ المبني للمجهول، <r v=\"Gal.3.15\"></r> (قارن <g>προ-κυρόω</g>).†</s>","en":"<f><o>κυρόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>κῦρος</g>, 1. <i>authority</i>. 2. <i>validity</i>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H6965\">קום</h>;]</e> </et> <s><b>to confirm</b>, <b>ratify</b>, <b>make valid</b>: <r v=\"2Cor.2.8\"></r>; pass., <r v=\"Gal.3.15\"></r> (cf. <g>προ-κυρόω</g>).†</s>"},"G2907":{"l":"κρέας","o":2,"ar":"<f><o>κρέας</o>، <g>-έως</g>، الجمع <g>κρέα</g>،</f> <s><b>لحم</b>: <r v=\"Rom.14.21\"></r>، <r v=\"1Cor.8.13\"></r>.†</s>","en":"<f><o>κρέας</o>, <g>-έως</g>, pl., <g>κρέα</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1320\">בָּשָׂר</h> (freq.);]</e> </et> <s><b>flesh</b>, <b>meat</b>: <r v=\"Rom.14.21\"></r>, <r v=\"1Cor.8.13\"></r>.†</s>"},"G2902":{"l":"κρατέω","o":47,"ar":"<f><o>κρατέω</o>، <g>-ῶ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>يكون قويًّا</b>، <b>مقتدرًا</b>، ومن ثمّ <b>يحكم</b>، <b>يتسلط</b>، <b>يغلب</b> (وفي السبعينية: <r v=\"Ezra.1.1\"></r>، <r v=\"1Esd.4.38\"></r>، <r v=\"Wis.14.19\"></r>، وفي مواضع أخرى).</s> <s n=\"2.\"><b>يستولي على</b>، <b>يحصل على</b>، <b>يمسك</b>: مع مضاف إليه الشيء، <r v=\"Acts.27.13\"></r>؛ <g>τ. χειρός</g> (أمسك بيدها/بيده)، <r v=\"Matt.9.25\"></r>، <r v=\"Mark.1.31\"></r> <r v=\"Mark.5.41\"></r> <r v=\"Mark.9.27\"></r>، <r v=\"Luke.8.54\"></r>؛ مع منصوب الشيء، <r v=\"Matt.12.11\"></r>؛ مع منصوب الشخص (يقبض على)، <r v=\"Matt.14.3\"></r> <r v=\"Matt.18.28\"></r> <r v=\"Matt.21.46\"></r> <r v=\"Matt.22.6\"></r> <r v=\"Matt.26.4\"></r>، <r v=\"Matt.26.48\"></r> وما يليه، <r v=\"Mark.3.21\"></r> <r v=\"Mark.6.17\"></r> <r v=\"Mark.12.12\"></r> <r v=\"Mark.14.1\"></r>، <r v=\"Mark.14.44\"></r> وما يليه، <r v=\"Acts.3.11\"></r> <r v=\"Acts.24.6\"></r>، <r v=\"Rev.20.2\"></r> (قارن <r v=\"2Sam.6.6\"></r>).</s> <s n=\"3.\"><b>يمسك</b>، <b>يتمسك بـ</b>: مع منصوب الشيء، <g>ἐν τ. δεξιᾷ</g>، <r v=\"Rev.2.1\"></r>. مجازيًا: مع منصوب الشخص، المبني للمجهول، <r v=\"Acts.2.24\"></r>؛ مع منصوب الشيء، <r v=\"Rev.2.13\"></r>، <r v=\"Rev.2.25\"></r> <r v=\"Rev.3.11\"></r>؛ <g>τ. κεφαλήν</g> (أي المسيح)، <r v=\"Col.2.19\"></r>؛ <g>τ. παράδοσιν</g> (<g>-εις</g>)، <g>λόγον, διδαχήν</g>، <r v=\"Mark.7.3\"></r>، <r v=\"Mark.7.4\"></r>، <r v=\"Mark.7.8\"></r> <r v=\"Mark.9.10\"></r>، <r v=\"2Thess.2.15\"></r>، <r v=\"Rev.2.14\"></r>، <r v=\"Rev.2.15\"></r>؛ مع مضاف إليه الشيء، <r v=\"Heb.4.14\"></r> <r v=\"Heb.6.18\"></r>؛ عن الخطايا: <b>يُمسك</b> (لا يغفر)، <r v=\"John.20.23\"></r>؛ عن المنع والكبح، يليه <g>ἵνα μή</g>، <r v=\"Rev.7.1\"></r>؛ المبني للمجهول، يليه <g>τοῦ μή</g> (أُمسكت أعينهما عن...)، <r v=\"Luke.24.16\"></r>.†</s>","en":"<f><o>κρατέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>κράτος</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2388\">חזק</h> hi., also for <h n=\"H270\">אחז</h>, etc.;]</e> </et> <s n=\"1.\"><b>to be strong</b>, <b>mighty</b>, hence, <b>to rule</b>, <b>be master</b>, <b>prevail</b> (so chiefly in cl.; in LXX: <r v=\"Ezra.1.1\"></r>, <r v=\"1Esd.4.38\"></r>, <r v=\"Wis.14.19\"></r>, al.).</s> <s n=\"2.\"><b>to get possession of</b>, <b>obtain</b>, <b>take hold of</b> (Hdt., Thuc., al.): c. gen. rei (M, <i>Pr.</i>, 65), <r v=\"Acts.27.13\"></r>; <g>τ. χειρός</g>, <r v=\"Matt.9.25\"></r>, <r v=\"Mark.1.31\"></r> <r v=\"Mark.5.41\"></r> <r v=\"Mark.9.27\"></r>, <r v=\"Luke.8.54\"></r>; c. acc. rei, <r v=\"Matt.12.11\"></r>; c. acc. pers., <r v=\"Matt.14.3\"></r> <r v=\"Matt.18.28\"></r> <r v=\"Matt.21.46\"></r> <r v=\"Matt.22.6\"></r> <r v=\"Matt.26.4\"></r>, <r v=\"Matt.26.48\"></r> ff., <r v=\"Mark.3.21\"></r> <r v=\"Mark.6.17\"></r> <r v=\"Mark.12.12\"></r> <r v=\"Mark.14.1\"></r>, <r v=\"Mark.14.44\"></r> ff., <r v=\"Acts.3.11\"></r> <r v=\"Acts.24.6\"></r>, <r v=\"Rev.20.2\"></r> (cf. <r v=\"2Sam.6.6\"></r>).</s> <s n=\"3.\"><b>to hold</b>, <b>hold fast</b> (Æsch., Polyb., al.): c. acc. rei, <g>ἐν τ. δεξιᾷ</g>, <r v=\"Rev.2.1\"></r>. Metaph.: c. acc. pers., pass., <r v=\"Acts.2.24\"></r>; c. acc. rei, <r v=\"Rev.2.13\"></r>, <r v=\"Rev.2.25\"></r> <r v=\"Rev.3.11\"></r>; <g>τ. κεφαλήν</g> (i.e. Christ), <r v=\"Col.2.19\"></r>; <g>τ. παράδοσιν</g> (<g>-εις</g>), <g>λόγον, διδαχήν</g>, <r v=\"Mark.7.3\"></r>, <r v=\"Mark.7.4\"></r>, <r v=\"Mark.7.8\"></r> <r v=\"Mark.9.10\"></r>, <r v=\"2Thess.2.15\"></r>, <r v=\"Rev.2.14\"></r>, <r v=\"Rev.2.15\"></r>; c. gen. rei, <r v=\"Heb.4.14\"></r> <r v=\"Heb.6.18\"></r>; of sins, <b>to retain</b>, <r v=\"John.20.23\"></r>; of restraint, seq. <g>ἵνα μή</g>, <r v=\"Rev.7.1\"></r>; pass., seq. <g>τοῦ μή</g>, <r v=\"Luke.24.16\"></r>.†</s>"},"G2923":{"l":"κριτής","o":19,"ar":"<f><o>κριτής</o>، <g>-οῦ, ὁ</g></f> <s><b>قاضٍ، ديّان</b>: <r v=\"Matt.5.25\"></r>، <r v=\"Luke.12.14\"></r>، <r v=\"Luke.12.58\"></r> <r v=\"Luke.18.2\"></r>؛ <g>τ. ἀδικίας</g> (قاضي الظلم)، <r v=\"Luke.18.6\"></r>؛ مع مضاف إليه الشيء (مفعولاً)، <r v=\"Acts.18.15\"></r>، <r v=\"Jas.4.11\"></r>؛ (للصفة)، <g>διαλογισμῶν πονηρῶν</g> (قضاة أفكار شريرة)، <r v=\"Jas.2.4\"></r>؛ عن الوالي الروماني، <r v=\"Acts.24.10\"></r>؛ عن الله، <r v=\"Heb.12.23\"></r>، <r v=\"Jas.4.12\"></r>؛ المسيح، <r v=\"Acts.10.42\"></r>، <r v=\"2Tim.4.8\"></r>، <r v=\"Jas.5.9\"></r>؛ عن الذين يُتّخذ سلوكهم مقياسًا للحكم، <r v=\"Matt.12.27\"></r>، <r v=\"Luke.11.19\"></r>؛ بمعنى العهد القديم (<r v=\"Judg.2.16\"></r>، <r v=\"Ruth.1.1\"></r>، وفي مواضع أخرى)، عن حاكم في إسرائيل، <r v=\"Acts.13.20\"></r>.†</s>","en":"<f><o>κριτής</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>κρίνω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H8199\">שֹׁפַט</h>;]</e> </et> <s><b>a judge</b>: <r v=\"Matt.5.25\"></r>, <r v=\"Luke.12.14\"></r>, <r v=\"Luke.12.58\"></r> <r v=\"Luke.18.2\"></r>; <g>τ. ἀδικίας</g>, <r v=\"Luke.18.6\"></r>; c. gen. rei (obj.), <r v=\"Acts.18.15\"></r>, <r v=\"Jas.4.11\"></r>; (qual.), <g>διαλογισμῶν πονηρῶν</g>, <r v=\"Jas.2.4\"></r>; of a Roman procurator, <r v=\"Acts.24.10\"></r>; of God, <r v=\"Heb.12.23\"></r>, <r v=\"Jas.4.12\"></r>; Christ, <r v=\"Acts.10.42\"></r>, <r v=\"2Tim.4.8\"></r>, <r v=\"Jas.5.9\"></r>; of those whose conduct is made a standard for judging, <r v=\"Matt.12.27\"></r>, <r v=\"Luke.11.19\"></r>; in the OT sense (<r v=\"Judg.2.16\"></r>, <r v=\"Ruth.1.1\"></r>, al), of a ruler in Israel, <r v=\"Acts.13.20\"></r>.†</s> <sy><i>SYN.</i>: <g>δικάστης</g>, q.v.</sy>"},"G2989":{"l":"λάμπω","o":7,"ar":"<f><o>λάμπω</o>،</f> <s><b>يضيء، يلمع</b>: <r v=\"Matt.5.15\"></r>، <r v=\"Matt.5.16\"></r> <r v=\"Matt.17.2\"></r>، <r v=\"Luke.17.24\"></r>، <r v=\"Acts.12.7\"></r>، <r v=\"2Cor.4.6\"></r> (قارن <g>ἐκ-</g>، <g>περι-λάμπω</g>).†</s>","en":"<f><o>λάμπω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5050\">נגהּ</h>, etc.;]</e> </et> <s><b>to shine</b>: <r v=\"Matt.5.15\"></r>, <r v=\"Matt.5.16\"></r> <r v=\"Matt.17.2\"></r>, <r v=\"Luke.17.24\"></r>, <r v=\"Acts.12.7\"></r>, <r v=\"2Cor.4.6\"></r> (cf. <g>ἐκ-</g>, <g>περι-λάμπω</g>).†</s>"},"G2995":{"l":"λάρυγξ","o":1,"ar":"<f><o>λάρυγξ</o>، <g>-γγος, ὁ</g>،</f> <s><b>الحنجرة</b>، <b>الحلق</b>: مجازيًا عن الكلام (قارن <r v=\"Sir.6.5\"></r>)، <r v=\"Rom.3.13\"></r><i>(السبعينية)</i>.†</s>","en":"<f><o>λάρυγξ</o>, <g>-γγος, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2441\">חֵךְ</h>, <r v=\"Job.6.30\"></r>, al; <r v=\"Ps.5.9\"></r> (<h n=\"H1627\">גָּרוֹן</h>);]</e> </et> <s>the <b>larynx</b>, <b>throat</b>: metaph., of speech (cf. <r v=\"Sir.6.5\"></r>), <r v=\"Rom.3.13\"></r><i>(LXX)</i>.†</s>"},"G2983":{"l":"λαμβάνω","o":258,"ar":"<f><o>λαμβάνω</o>،</f> <s> <s n=\"1.\"><b>يأخذ</b>، <b>يمسك</b>: مطلقًا، <r v=\"Matt.26.26\"></r>، <r v=\"Mark.14.22\"></r>؛ مع المنصوب للشيء، <r v=\"Matt.5.40\"></r>، <r v=\"Matt.26.52\"></r>، وفي مواضع أخرى كثيرة؛ مع المنصوب للشخص، <r v=\"Matt.21.35\"></r>، <r v=\"Mark.12.3\"></r>، وفي مواضع أخرى؛ <g>λαβών</g> على سبيل الحشو، <r v=\"Matt.13.31\"></r>، <r v=\"Matt.14.19\"></r>، وفي مواضع أخرى؛ وكذلك في الإخباري، <r v=\"Mark.7.27\"></r>، <r v=\"John.19.1\"></r>، <r v=\"John.19.40\"></r>، <r v=\"Rev.8.5\"></r>، وفي مواضع أخرى؛ مجازيًا، مع المنصوب للشيء، <g>ἀφορμήν</g>، <r v=\"Rom.7.8\"></r>، <r v=\"Rom.7.11\"></r>؛ <g>ὑδόδειγμα</g>، <r v=\"Jas.5.10\"></r>؛ ونفسه مع المنصوب للشخص، <g>φόβος</g>، <r v=\"Luke.7.16\"></r>؛ <g>πνεῦμα</g>، <r v=\"Luke.9.39\"></r>؛ <g>πειρασμός</g>، <r v=\"1Cor.10.13\"></r>؛ التام بمعنى الماضي البسيط، <r v=\"Rev.5.7\"></r>، <r v=\"Rev.8.5\"></r>، وفي مواضع أخرى.</s> <s n=\"2.\"><b>يقبل، ينال</b>: مطلقًا، عكس <g>αἰτεῖν</g>، <r v=\"Matt.7.8\"></r>، وفي مواضع أخرى؛ <g>διδόναι</g>، <r v=\"Matt.10.8\"></r>، <r v=\"Acts.20.35\"></r>؛ مع المنصوب للشيء، <r v=\"Matt.27.6\"></r>، <r v=\"Mark.10.30\"></r>، وفي مواضع أخرى كثيرة؛ مع المنصوب للشخص، <r v=\"John.6.21\"></r>، <r v=\"John.13.20\"></r>، <r v=\"John.19.27\"></r>، <r v=\"2John.1.10\"></r>؛ <g>ῥαπίσμασιν</g> (استعمال عامّي)، <r v=\"Mark.14.65\"></r>؛ مجازيًا، <g>τ. λόγον</g>، <r v=\"Matt.13.20\"></r>، <r v=\"Mark.4.16\"></r>؛ <g>τ. μαρτυρίαν</g>، <r v=\"John.3.11\"></r>؛ <g>τ. ῥήματα</g>، <r v=\"John.12.48\"></r>؛ <g>πρόσωπον</g> (العبرية <h n=\"H5375,H6440\">נָשָׂא פָּנִים</h>)، <r v=\"Luke.20.21\"></r>، <r v=\"Gal.2.6\"></r>؛ <g>ζωὴν αἰώνιον</g>، <r v=\"Mark.10.30\"></r> (قارن <g>ἀνα-</g>، <g>ἀντι-</g>، <g>συν-αντι-</g> (<g>-μαι</g>)، <g>ἀπο-</g>، <g>ἐπι-</g>، <g>κατα-</g>، <g>μετα-</g>، <g>παρα-</g>، <g>συν-παρα-</g>، <g>προ-</g>، <g>προσ-</g>، <g>συν-</g>، <g>συν-περι-</g>، <g>ὑπο-λαμβάνω</g>).</s> </s>","en":"<f><o>λαμβάνω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H3947\">לקח</h>, also for <h n=\"H5375\">נשׂא</h>, <h n=\"H3920\">לכד</h>, <h n=\"H270\">אחז</h>, etc.;]</e> </et> <s> <s n=\"1.\"><b>to take</b>, <b>lay hold of</b>: absol., <r v=\"Matt.26.26\"></r>, <r v=\"Mark.14.22\"></r>; c. acc. rei, <r v=\"Matt.5.40\"></r> <r v=\"Matt.26.52\"></r>, al. mult.; c. acc. pers., <r v=\"Matt.21.35\"></r>, <r v=\"Mark.12.3\"></r>, al.; pleonastic <g>λαβών</g> (M, <i>Pr.</i>, 230; Bl., §74, 2), <r v=\"Matt.13.31\"></r> <r v=\"Matt.14.19\"></r>, al.; so also indic., <r v=\"Mark.7.27\"></r>, <r v=\"John.19.1\"></r>, <r v=\"John.19.40\"></r>, <r v=\"Rev.8.5\"></r>, al.; metaph., c. acc. rei, <g>ἀφορμήν</g>, <r v=\"Rom.7.8\"></r>, <r v=\"Rom.7.11\"></r>; <g>ὑδόδειγμα</g>, <r v=\"Jas.5.10\"></r>; id. c. acc. pers., <g>φόβος</g>, <r v=\"Luke.7.16\"></r>; <g>πνεῦμα</g>, <r v=\"Luke.9.39\"></r>; <g>πειρασμός</g>, <r v=\"1Cor.10.13\"></r>; aoristic pf. (M, <i>Pr.</i>, 145, 238; Bl., § 59, 4), <r v=\"Rev.5.7\"></r> <r v=\"Rev.8.5\"></r>, al.</s> <s n=\"2.\"><b>to receive</b>: absol., opp. to <g>αἰτεῖν</g>, <r v=\"Matt.7.8\"></r>, al.; <g>διδόναι</g>, <r v=\"Matt.10.8\"></r>, <r v=\"Acts.20.35\"></r>; c. acc. rei, <r v=\"Matt.27.6\"></r>, <r v=\"Mark.10.30\"></r>, al. mult.; c. acc. pers., <r v=\"John.6.21\"></r> <r v=\"John.13.20\"></r> <r v=\"John.19.27\"></r>, <r v=\"2John.1.10\"></r>; <g>ῥαπίσμασιν</g> (a vulgarism; Bl., § 38, 3), <r v=\"Mark.14.65\"></r>; metaph., <g>τ. λόγον</g>, <r v=\"Matt.13.20\"></r>, <r v=\"Mark.4.16\"></r>; <g>τ. μαρτυρίαν</g>, <r v=\"John.3.11\"></r>; <g>τ. ῥήματα</g>, <r v=\"John.12.48\"></r>; <g>πρόσωπον</g> (Heb. <h n=\"H5375,H6440\">נָשָׂא פָּנִים</h>, Dalman, <i>Words</i>, 30), <r v=\"Luke.20.21\"></r>, <r v=\"Gal.2.6\"></r>; <g>ζωὴν αἰώνιον</g> (Dalman, <i>op. cit.</i>, 124 f.), <r v=\"Mark.10.30\"></r> (cf. <g>ἀνα-</g>, <g>ἀντι-</g>, <g>συν-αντι-</g> (<g>-μαι</g>), <g>ἀπο-</g>, <g>ἐπι-</g>, <g>κατα-</g>, <g>μετα-</g>, <g>παρα-</g>, <g>συν-παρα-</g>, <g>προ-</g>, <g>προσ-</g>, <g>συν-</g>, <g>συν-περι-</g>, <g>ὑπο-λαμβάνω</g>).</s> </s>"},"G2992":{"l":"λαός","o":142,"ar":"<f><o>λαός</o>، <g>-οῦ, ὁ</g>،</f> <s n=\"1.\"><b>الشعب</b> عامةً، وخاصةً عن الناس المجتمعين: <r v=\"Matt.27.25\"></r>، <r v=\"Luke.1.21\"></r>، <r v=\"Luke.3.15\"></r>، وفي مواضع أخرى؛ في الجمع، <r v=\"Acts.4.27\"></r>.</s> <s n=\"2.\"><b>شعب</b>، أي الذين من جنس واحد ولغة واحدة (وفي السبعينية، <r v=\"Gen.26.11\"></r>، <r v=\"Exod.9.16\"></r>، وفي مواضع أخرى): مقرونًا بـ <g>γλῶσσα</g>، <g>φυλή</g>، <g>ἔθνος</g>، <r v=\"Rev.5.9\"></r>، <r v=\"Rev.7.9\"></r>، <r v=\"Rev.11.9\"></r>، وفي مواضع أخرى؛ في الجمع، <r v=\"Luke.2.31\"></r>، <r v=\"Rom.15.11\"></r>؛ وخاصةً، كما في السبعينية دائمًا تقريبًا، عن إسرائيل، <r v=\"Matt.4.23\"></r>، <r v=\"Mark.7.6\"></r>، <r v=\"Luke.2.10\"></r>، <r v=\"John.11.50\"></r>، <r v=\"Heb.2.17\"></r>، وفي مواضع أخرى؛ عكس <g>τ. ἔθνη</g>، <r v=\"Acts.26.17\"></r>، <r v=\"Acts.26.23\"></r>، <r v=\"Rom.15.10\"></r>؛ <g>οἱ πρεσβύτεροι</g> (<g>πρῶτοι</g>، إلخ) <g>τοῦ λ.</g>، <r v=\"Matt.21.23\"></r>، <r v=\"Luke.19.17\"></r>، <r v=\"Acts.4.8\"></r>، وفي مواضع أخرى؛ <g>ὁ λ. μου</g> (<g>αὐτοῦ, τ. θεοῦ</g>)، <r v=\"Matt.2.6\"></r>، <r v=\"Luke.1.68\"></r>، <r v=\"Heb.11.25\"></r>، وفي مواضع أخرى؛ عن عامة الشعب تمييزًا لهم عن الرؤساء والكهنة (قارن <r v=\"1Esd.1.10\"></r>، <r v=\"Jdt.8.9\"></r>، وفي مواضع أخرى)، <r v=\"Matt.26.5\"></r>، <r v=\"Luke.20.19\"></r>، <r v=\"Heb.5.3\"></r>، وفي مواضع أخرى؛ عن المسيحيين بوصفهم شعب الله، <r v=\"Acts.15.14\"></r>، <r v=\"Rom.9.25\"></r>، <r v=\"Rom.9.26\"></r>، <r v=\"Heb.4.9\"></r>؛ <g>περιούσιος</g>، <r v=\"Titus.2.14\"></r>؛ <g>εἰς περιποίησιν</g>، <r v=\"1Pet.2.9\"></r> <i>(السبعينية)</i>.</s>","en":"<f><o>λαός</o>, <g>-οῦ, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX very freq. for <h n=\"H5971\">עַם</h>, <r v=\"Gen.14.16\"></r>, al.; occasionally for <h n=\"H3816\">לְאֹם</h> ( <r v=\"Gen.25.23\"></r>, al.), etc.;]</e> </et> a word rarely found in Att. prose; <s n=\"1.\"><b>the people</b> at large (Hom., al.), esp. of people assembled: <r v=\"Matt.27.25\"></r>, <r v=\"Luke.1.21\"></r> <r v=\"Luke.3.15\"></r> al.; pl. (Hom., al., <g>π.</g>; v. MM, xvi), <r v=\"Acts.4.27\"></r>.</s> <s n=\"2.\"><b>a people</b>, those of the same race and language (Pind., Æsch., al.: in LXX, <r v=\"Gen.26.11\"></r>, <r v=\"Exod.9.16\"></r>, al.): joined with <g>γλῶσσα</g>, <g>φυλή</g>, <g>ἔθνος</g>, <r v=\"Rev.5.9\"></r> <r v=\"Rev.7.9\"></r> <r v=\"Rev.11.9\"></r>, al.; pl., <r v=\"Luke.2.31\"></r>, <r v=\"Rom.15.11\"></r>; esp. as almost always in LXX, of Israel, <r v=\"Matt.4.23\"></r>, <r v=\"Mark.7.6\"></r>, <r v=\"Luke.2.10\"></r>, <r v=\"John.11.50\"></r>, <r v=\"Heb.2.17\"></r>, al.; opp. to <g>τ. ἔθνη</g>, <r v=\"Acts.26.17\"></r>, <r v=\"Acts.26.23\"></r>, <r v=\"Rom.15.10\"></r>; <g>οἱ πρεσβύτεροι</g> (<g>πρῶτοι</g>, etc.) <g>τοῦ λ.</g>, <r v=\"Matt.21.23\"></r>, <r v=\"Luke.19.17\"></r>, <r v=\"Acts.4.8\"></r>, al.; <g>ὁ λ. μου</g> (<g>αὐτοῦ, τ. θεοῦ</g>), <r v=\"Matt.2.6\"></r>, <r v=\"Luke.1.68\"></r>, <r v=\"Heb.11.25\"></r>, al.; of the people disting. from the rulers and priests ( <r v=\"1Esd.1.10\"></r>, <r v=\"Jdt.8.9\"></r>, al.), <r v=\"Matt.26.5\"></r>, <r v=\"Luke.20.19\"></r>, <r v=\"Heb.5.3\"></r>, al.; of Christians, as the people of God, <r v=\"Acts.15.14\"></r>, <r v=\"Rom.9.25\"></r>, <r v=\"Rom.9.26\"></r>, <r v=\"Heb.4.9\"></r>; <g>περιούσιος</g>, <r v=\"Titus.2.14\"></r>; <g>εἰς περιποίησιν</g>, <r v=\"1Pet.2.9\"></r><i>(LXX)</i>.</s> <sy><i>SYN.</i>: v.s. <g>δῆμος</g>.</sy>"},"G2908":{"l":"κρείσσων","o":19,"ar":"<f><o>κρείσσων</o></f> <s><b>أفضل</b>؛ <s n=\"(a)\">من جهة النفع أو الفائدة: <r v=\"1Cor.11.17\"></r>، <r v=\"Heb.11.40\"></r>، <r v=\"Heb.12.24\"></r>؛ <g>πολλῷ μᾶλλον κ.</g>، <r v=\"Phil.1.23\"></r>؛ <g>κρεῖσσον ποιεῖν</g>، <r v=\"1Cor.7.38\"></r>؛ <g>ἐστιν</g>، يليه المصدر، <r v=\"1Cor.7.9\"></r>، <r v=\"2Pet.2.21\"></r>؛</s> <s n=\"(b)\">من جهة السموّ: <r v=\"Heb.1.4\"></r>، <r v=\"Heb.6.9\"></r>، <r v=\"Heb.7.7\"></r>، <r v=\"Heb.7.19\"></r>، <r v=\"Heb.7.22\"></r>، <r v=\"Heb.8.6\"></r>، <r v=\"Heb.9.23\"></r>، <r v=\"Heb.10.34\"></r>، <r v=\"Heb.11.16\"></r>، <r v=\"Heb.11.35\"></r>؛ <g>κ. ἐστι</g>، يليه المصدر، <r v=\"1Pet.3.17\"></r>.†</s> </s>","en":"<f><o>κρείσσων</o></f> <et> <e t=\"derivation\">(Epic and old Att.) and <g>κρείττων</g> (later Att.), prop. comparat. of <g>κρατύς</g>, <i>strong</i>, but in sense often (as in cl., v. LS, s.v.) as comparat. of <g>ἀγαθός</g>,</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2896\">טוֹב</h>;]</e> </et> <s><b>better</b>; <s n=\"(a)\">as to advantage or usefulness: <r v=\"1Cor.11.17\"></r>, <r v=\"Heb.11.40\"></r> <r v=\"Heb.12.24\"></r>; <g>πολλῷ μᾶλλον κ.</g>, <r v=\"Phil.1.23\"></r>; <g>κρεῖσσον ποιεῖν</g>, <r v=\"1Cor.7.38\"></r>; <g>ἐστιν</g>, seq. inf., <r v=\"1Cor.7.9\"></r>, <r v=\"2Pet.2.21\"></r>;</s> <s n=\"(b)\">as to excellence: <r v=\"Heb.1.4\"></r> <r v=\"Heb.6.9\"></r> <r v=\"Heb.7.7\"></r>, <r v=\"Heb.7.19\"></r>, <r v=\"Heb.7.22\"></r> <r v=\"Heb.8.6\"></r> <r v=\"Heb.9.23\"></r> <r v=\"Heb.10.34\"></r> <r v=\"Heb.11.16\"></r>, <r v=\"Heb.11.35\"></r>; <g>κ. ἐστι</g>, seq. inf., <r v=\"1Pet.3.17\"></r>.†</s> </s>"},"G2921":{"l":"Κρίσπος","o":2,"ar":"<f><o>Κρίσπος</o>، <g>-ου, ὁ</g>،</f> <s><b>كريسبس</b>: <r v=\"Acts.18.8\"></r>، <r v=\"1Cor.1.14\"></r>.†</s>","en":"<f><o>Κρίσπος</o>, <g>-ου, ὁ</g>,</f> <s><b>Crispus</b>: <r v=\"Acts.18.8\"></r>, <r v=\"1Cor.1.14\"></r>.†</s>"},"G2909":{"l":"κρείσσων","o":19,"ar":"<f><o>κρείσσων</o></f> <s><b>أفضل</b>، <b>خير</b>؛ <s n=\"(a)\">من جهة النفع أو الفائدة: <r v=\"1Cor.11.17\"></r>، <r v=\"Heb.11.40\"></r>، <r v=\"Heb.12.24\"></r>؛ <g>πολλῷ μᾶλλον κ.</g>: <r v=\"Phil.1.23\"></r>؛ <g>κρεῖσσον ποιεῖν</g>: <r v=\"1Cor.7.38\"></r>؛ <g>ἐστιν</g>، يليه المصدر: <r v=\"1Cor.7.9\"></r>، <r v=\"2Pet.2.21\"></r>؛</s> <s n=\"(b)\">من جهة السموّ والتفوّق: <r v=\"Heb.1.4\"></r>، <r v=\"Heb.6.9\"></r>، <r v=\"Heb.7.7\"></r>، <r v=\"Heb.7.19\"></r>، <r v=\"Heb.7.22\"></r>، <r v=\"Heb.8.6\"></r>، <r v=\"Heb.9.23\"></r>، <r v=\"Heb.10.34\"></r>، <r v=\"Heb.11.16\"></r>، <r v=\"Heb.11.35\"></r>؛ <g>κ. ἐστι</g>، يليه المصدر: <r v=\"1Pet.3.17\"></r>.†</s> </s>","en":"<f><o>κρείσσων</o></f> <et> <e t=\"derivation\">(Epic and old Att.) and <g>κρείττων</g> (later Att.), prop. comparat. of <g>κρατύς</g>, <i>strong</i>, but in sense often (as in cl., v. LS, s.v.) as comparat. of <g>ἀγαθός</g>,</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2896\">טוֹב</h>;]</e> </et> <s><b>better</b>; <s n=\"(a)\">as to advantage or usefulness: <r v=\"1Cor.11.17\"></r>, <r v=\"Heb.11.40\"></r> <r v=\"Heb.12.24\"></r>; <g>πολλῷ μᾶλλον κ.</g>, <r v=\"Phil.1.23\"></r>; <g>κρεῖσσον ποιεῖν</g>, <r v=\"1Cor.7.38\"></r>; <g>ἐστιν</g>, seq. inf., <r v=\"1Cor.7.9\"></r>, <r v=\"2Pet.2.21\"></r>;</s> <s n=\"(b)\">as to excellence: <r v=\"Heb.1.4\"></r> <r v=\"Heb.6.9\"></r> <r v=\"Heb.7.7\"></r>, <r v=\"Heb.7.19\"></r>, <r v=\"Heb.7.22\"></r> <r v=\"Heb.8.6\"></r> <r v=\"Heb.9.23\"></r> <r v=\"Heb.10.34\"></r> <r v=\"Heb.11.16\"></r>, <r v=\"Heb.11.35\"></r>; <g>κ. ἐστι</g>, seq. inf., <r v=\"1Pet.3.17\"></r>.†</s> </s>"},"G2927":{"l":"κρυπτός","o":17,"ar":"<f><o>κρυπτός</o>، <g>-ή, -όν</g></f> <s><b>مخفيّ</b>، <b>سرّي</b>: <r v=\"Matt.10.26\"></r>، <r v=\"Mark.4.22\"></r>، <r v=\"Luke.8.17\"></r> <r v=\"Luke.12.2\"></r>؛ <g>ὁ κ. τῆς καρδίας ἄνθρωπος</g>، <r v=\"1Pet.3.4\"></r>؛ المحايد، <g>ἐν τῷ κ.</g>، <r v=\"Matt.6.4\"></r>، <r v=\"Matt.6.6\"></r>؛ <g>ἐν κ.</g>، <r v=\"John.7.4\"></r>، <r v=\"John.7.10\"></r> <r v=\"John.18.20\"></r>؛ <g>ὁ ἐν κ. Ἰουδαῖος</g>، <r v=\"Rom.2.29\"></r>؛ جمع، <g>τὰ κ. τ. σκότους</g>، <r v=\"1Cor.4.5\"></r>؛ <g>τ. ἀνθρώπων</g>، <r v=\"Rom.2.16\"></r>؛ <g>τ. καρδίας</g>، <r v=\"1Cor.14.25\"></r>؛ <g>τ. αἰσχύνης</g>، <r v=\"2Cor.4.2\"></r>.†</s>","en":"<f><o>κρυπτός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(<g>κρύπτω</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H331\">אטם</h>, <h n=\"H4565\">מִסְתָּר</h>, etc.;]</e> </et> <s><b>hidden</b>, <b>secret</b>: <r v=\"Matt.10.26\"></r>, <r v=\"Mark.4.22\"></r>, <r v=\"Luke.8.17\"></r> <r v=\"Luke.12.2\"></r>; <g>ὁ κ. τῆς καρδίας ἄνθρωπος</g>, <r v=\"1Pet.3.4\"></r>; neut., <g>ἐν τῷ κ.</g>, <r v=\"Matt.6.4\"></r>, <r v=\"Matt.6.6\"></r>; <g>ἐν κ.</g>, <r v=\"John.7.4\"></r>, <r v=\"John.7.10\"></r> <r v=\"John.18.20\"></r>; <g>ὁ ἐν κ. Ἰουδαῖος</g>, <r v=\"Rom.2.29\"></r>; pl., <g>τὰ κ. τ. σκότους</g>, <r v=\"1Cor.4.5\"></r>; <g>τ. ἀνθρώπων</g>, <r v=\"Rom.2.16\"></r>; <g>τ. καρδίας</g>, <r v=\"1Cor.14.25\"></r>; <g>τ. αἰσχύνης</g>, <r v=\"2Cor.4.2\"></r>.†</s>"},"G2937":{"l":"κτίσις","o":19,"ar":"<f><o>κτίσις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>تأسيس</b>، <b>استيطان</b>، <b>إنشاء</b>.</s> <s n=\"2.\">في السبعينية والعهد الجديد، <s n=\"(a)\"><b>فعل الخلق</b>، <b>الخليقة</b>: <r v=\"Mark.10.6\"></r>، <r v=\"Mark.13.19\"></r>، <r v=\"Rom.1.20\"></r>، <r v=\"2Pet.3.4\"></r>؛</s> <s n=\"(b)\"><b>ما خُلق</b>، <b>خليقة</b>: <r v=\"Rom.1.25\"></r> <r v=\"Rom.8.39\"></r>، <r v=\"Heb.4.13\"></r>؛ <g>καινὴ κ.</g>، <r v=\"2Cor.5.17\"></r>، <r v=\"Gal.6.15\"></r>؛ <g>πάσῃ ἀνθρωπίνῃ κ.</g>، <r v=\"1Pet.2.13\"></r>؛ جمعيًّا، عن مجموع المخلوقات (<r v=\"Wis.19.6\"></r>، <r v=\"Jdt.16.14\"></r>)، <r v=\"Mark.16.15\"></r>، <r v=\"Col.1.15\"></r>، <r v=\"Col.1.23\"></r>، <r v=\"Heb.9.11\"></r>، <r v=\"Rev.3.14\"></r>؛ عن الخليقة غير العاقلة، <r v=\"Rom.8.19-Rom.8.22\"></r>.†</s> </s>","en":"<f><o>κτίσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>κτίζω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Ps.104.24\"></r> (<h n=\"H7075\">קִנְיָן</h>), <r v=\"Prov.1.13\"></r> A (<h n=\"H1952\">הוֹן</h>), <r v=\"Tob.8.5\"></r>, <r v=\"Wis.2.6\"></r>, <r v=\"Sir.16.17\"></r>, <r v=\"3Macc.2.2\"></r>, al.;]</e> </et> <s n=\"1.\"><b>a founding</b>, <b>settling</b>, <b>foundation</b> (cl.).</s> <s n=\"2.\">In LXX and NT, <s n=\"(a)\"><b>the act of creating</b>, <b>creation</b>: <r v=\"Mark.10.6\"></r> (Swete, in l.), <r v=\"Mark.13.19\"></r>, <r v=\"Rom.1.20\"></r>, <r v=\"2Pet.3.4\"></r>;</s> <s n=\"(b)\"><b>that which has been created</b>, <b>creation</b>: <r v=\"Rom.1.25\"></r> <r v=\"Rom.8.39\"></r>, <r v=\"Heb.4.13\"></r>; <g>καινὴ κ.</g>, <r v=\"2Cor.5.17\"></r>, <r v=\"Gal.6.15\"></r>; <g>πάσῃ ἀνθρωπίνῃ κ.</g> (Hort., in l.), <r v=\"1Pet.2.13\"></r>; collectively, of the sum of created things (<r v=\"Wis.19.6\"></r>, <r v=\"Jdt.16.14\"></r>), <r v=\"Mark.16.15\"></r>, <r v=\"Col.1.15\"></r>, <r v=\"Col.1.23\"></r>, <r v=\"Heb.9.11\"></r>, <r v=\"Rev.3.14\"></r>; of the irrational creation, <r v=\"Rom.8.19-Rom.8.22\"></r>.†</s> </s>"},"G2910":{"l":"κρεμάννυμι","o":7,"ar":"<f><o>κρεμάννυμι</o></f> <s>متعدٍّ: <b>علّق</b>، <b>دلّى</b>: مع المنصوب للشخص، يليه <g>ἐπὶ ξύλου</g>، <r v=\"Acts.5.30\"></r> <r v=\"Acts.10.39\"></r>؛ المبني للمجهول، <r v=\"Luke.23.39\"></r>؛ يليه <g>περί</g>، <r v=\"Matt.18.6\"></r>. الصيغة الوسطى <g>κρέμαμαι</g>، لازم: <b>تعلّق، كان معلَّقًا</b>: يليه <g>ἐκ</g>، <r v=\"Acts.28.4\"></r>؛ <g>ἐπὶ ξύλου</g>، <r v=\"Gal.3.13\"></r><i>(السبعينية)</i>؛ مجازيًا، يليه <g>ἐν</g>، <r v=\"Matt.22.40\"></r>.†</s>","en":"<f><o>κρεμάννυμι</o></f> <et> <e t=\"derivation\">(also <g>κρεμαννύω, κρεμάω</g>; the pres. is not found in NT),</e> <e t=\"septuagint\">[in LXX (where also <g>κρεμάζω</g>, <r v=\"Job.26.7\"></r>) chiefly for <h n=\"H8518\">תּלה</h>;]</e> </et> <s>trans., <b>to hang</b>, <b>suspend</b>: c. acc. pers., seq. <g>ἐπὶ ξύλου</g>, <r v=\"Acts.5.30\"></r> <r v=\"Acts.10.39\"></r>; pass., <r v=\"Luke.23.39\"></r>; seq. <g>περί</g>, <r v=\"Matt.18.6\"></r>. Mid., <g>κρέμαμαι</g>, intrans., <b>to hang</b>: seq. <g>ἐκ</g>, <r v=\"Acts.28.4\"></r>; <g>ἐπὶ ξύλου</g>, <r v=\"Gal.3.13\"></r><i>(LXX)</i>; metaph., seq. <g>ἐν</g>, <r v=\"Matt.22.40\"></r>.†</s>"},"G2970":{"l":"κῶμος","o":3,"ar":"<f>** <o>κῶμος</o>، <g>-ου, ὁ</g>،</f> <s><b>بَطَر</b>، <b>عربدة، قصف</b>: <r v=\"Rom.13.13\"></r>، <r v=\"Gal.5.21\"></r>، <r v=\"1Pet.4.3\"></r>.†</s>","en":"<f>** <o>κῶμος</o>, <g>-ου, ὁ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Wis.14.23\"></r>, <r v=\"2Macc.6.4\"></r>*;]</e> </et> <s><b>a revel</b>, <b>carousal</b>: <r v=\"Rom.13.13\"></r>, <r v=\"Gal.5.21\"></r>, <r v=\"1Pet.4.3\"></r>.†</s> <sy><i>SYN.</i>: v.s. <g>κραιπάλη</g>.</sy>"},"G2950":{"l":"κύμβαλον","o":1,"ar":"<f><o>κύμβαλον</o>، <g>-ου, τό</g></f> <s><b>صنج</b>: <r v=\"1Cor.13.1\"></r>.†</s>","en":"<f><o>κύμβαλον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>κύμβη</g>, <i>a cup</i>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4698\">מְצֵלֶת</h>;]</e> </et> <s><b>a cymbal</b>: <r v=\"1Cor.13.1\"></r>.†</s>"},"G2932":{"l":"κτάομαι","o":7,"ar":"<f><o>κτάομαι</o>، <g>-ῶμαι</g>،</f> <s>في المضارع والماضي الناقص والمستقبل والأوريست: <b>يقتني لنفسه</b>، <b>يحصل على</b>، <b>يربح</b>، <b>يكتسب</b> (أما التام والماضي الأتم، <i>اقتنى</i> ومن ثمّ <i>امتلك</i>، فلا يردان في العهد الجديد): مع المنصوب للشيء، <r v=\"Matt.10.9\"></r>، <r v=\"Luke.18.12\"></r>، <r v=\"Acts.8.20\"></r>؛ مع المضاف إليه للثمن، <r v=\"Acts.22.28\"></r>؛ <g>ἐκ</g> مع المضاف إليه للثمن، <r v=\"Acts.1.18\"></r>؛ <g>τ. ψυχὰς ὑμῶν</g>، <r v=\"Luke.21.19\"></r>؛ <g>τ. ἑαυτοῦ σκεῦος κτᾶσθαι</g>، <r v=\"1Thess.4.4\"></r> (إن كان <g>σ.</g> = <i>الجسد</i> فيجب أن يكون <g>κ.</g> بمعنى التام <g>κέκτημαι</g>؛ لكن الأكثر أن يُفهم <g>σ.</g> بمعنى <i>الزوجة</i>).†</s>","en":"<f><o>κτάομαι</o>, <g>-ῶμαι</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7069\">קנה</h>;]</e> </et> <s>in pres., impf., fut. and aor., <b>to procure for oneself</b>, <b>get</b>, <b>gain</b>, <b>acquire</b> (the pf. and plpf., <i>to have acquired</i>, hence <i>to possess</i>, do not occur in NT): c. acc. rei, <r v=\"Matt.10.9\"></r>, <r v=\"Luke.18.12\"></r>, <r v=\"Acts.8.20\"></r>; c. gen. pret., <r v=\"Acts.22.28\"></r>; <g>ἐκ</g> c. gen. pret., <r v=\"Acts.1.18\"></r>; <g>τ. ψυχὰς ὑμῶν</g> (MM, xvi), <r v=\"Luke.21.19\"></r>; <g>τ. ἑαυτοῦ σκεῦος κτᾶσθαι</g>, <r v=\"1Thess.4.4\"></r> (where if <g>σ.</g> = <i>body</i>, <g>κ.</g> must = pf., <g>κέκτημαι</g>; v. MM, xvi; M, <i>Th.</i>, in l.; Field, <i>Notes</i>, 72 f. But <g>σ.</g> is most freq. taken as = <i>wife</i>; v. Thayer, s.v.; Lft., <i>Notes</i>, 53 ff.; <i>ICC</i>, in l.).†</s>"},"G2961":{"l":"κυριεύω","o":7,"ar":"<f><o>κυριεύω</o></f> <s><b>يكون ربًّا</b> أو <b>سيدًا على</b>، <b>يسود</b> (<b>على</b>): مع المضاف إليه للمفعول، <r v=\"Luke.22.25\"></r>، <r v=\"Rom.14.9\"></r>، <r v=\"2Cor.1.24\"></r>؛ مطلقًا، <r v=\"1Tim.6.15\"></r>؛ ومجازيًا: <g>ὁ θάνατος</g>، <r v=\"Rom.6.9\"></r>؛ <g>ἡ ἁμαρτία</g>، <r v=\"Rom.6.14\"></r>؛ <g>ὁ νόμος</g>، <r v=\"Rom.7.1\"></r> (قارن <g>κατα-κυριεύω</g>).†</s>","en":"<f><o>κυριεύω</o></f> <et> <e t=\"derivation\">(&lt; <g>κύριος</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4911\">משׁל</h>;]</e> </et> <s><b>to be lord</b> or <b>master of</b>, <b>to rule</b> (<b>over</b>): c. gen. obj., <r v=\"Luke.22.25\"></r>, <r v=\"Rom.14.9\"></r>, <r v=\"2Cor.1.24\"></r>; absol., <r v=\"1Tim.6.15\"></r>; metaph., <g>ὁ θάνατος</g>, <r v=\"Rom.6.9\"></r>; <g>ἡ ἁμαρτία</g>, <r v=\"Rom.6.14\"></r>; <g>ὁ νόμος</g>, <r v=\"Rom.7.1\"></r> (cf. <g>κατα-κυριεύω</g>).†</s>"},"G2934":{"l":"κτῆνος","o":4,"ar":"<f><o>κτῆνος</o>، <g>-ους, τό</g></f> <s><b>بهيمة</b>، و(خاصةً في اليونانية المتأخرة) <b>دابّة</b>: <r v=\"Luke.10.34\"></r>؛ في الجمع، <r v=\"Acts.23.24\"></r>، <r v=\"Rev.18.13\"></r>؛ عن ذوات الأربع مقابل الأسماك والطيور (قارن <r v=\"Gen.1.25\"></r>)، <r v=\"1Cor.15.39\"></r>.†</s>","en":"<f><o>κτῆνος</o>, <g>-ους, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>κτάομαι</g>, hence primarily <i>a possession</i>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H929\">בְּהֵמָה</h>, <r v=\"Gen.1.25\"></r>, al., also for <h n=\"H4735\">מִקְנֶה</h>, <h n=\"H6792\">צֹנֵא</h>, etc.;]</e> </et> <s><b>a beast</b>, (in late Gk. esp.) <b>a beast of burden</b>: <r v=\"Luke.10.34\"></r> pl. (as chiefly in cl.), <r v=\"Acts.23.24\"></r>, <r v=\"Rev.18.13\"></r>; of quadrupeds, as opp. to fishes and birds (cf. <r v=\"Gen.1.25\"></r>), <r v=\"1Cor.15.39\"></r>.†</s>"},"G2922":{"l":"κριτήριον","o":3,"ar":"<f><o>κριτήριον</o>، <g>-ου, τό</g></f> <s n=\"1.\"><b>وسيلة للحكم</b>، <b>محكّ</b>، <b>معيار</b>.</s> <s n=\"2.\"><b>محكمة، مجلس قضاء</b>: <r v=\"1Cor.6.2\"></r>، <r v=\"1Cor.6.4\"></r>، <r v=\"Jas.2.6\"></r>.†</s>","en":"<f><o>κριτήριον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>κριτής</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"1Kgs.7.7\"></r> (<h n=\"H4941\">מִשְׁפָּט</h>), <r v=\"Dan.7.10\"></r>, <r v=\"Dan.7.26\"></r>, (<h n=\"H1779\">דִּין</h>), <r v=\"Sus.1.49\"></r>, <r v=\"Exod.21.6\"></r>, <r v=\"Judg.5.10\"></r>*;]</e> </et> <s n=\"1.\"><b>a means of judging</b>, <b>test</b>, <b>criterion</b>.</s> <s n=\"2.\"><b>a tribunal</b>: <r v=\"1Cor.6.2\"></r>, <r v=\"1Cor.6.4\"></r>, <r v=\"Jas.2.6\"></r>.†</s>"},"G2920":{"l":"κρίσις","o":47,"ar":"<f><o>κρίσις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>فصل، تمييز</b>، <b>اختيار</b>.</s> <s n=\"2.\"><b>قرار</b>، <b>حكم، قضاء</b>: <r v=\"John.8.16\"></r>، <r v=\"1Tim.5.24\"></r>، <r v=\"2Pet.2.11\"></r>، <r v=\"Jude.1.9\"></r>؛ <g>κ. κρίνειν</g>، <r v=\"John.7.24\"></r>؛ بالمعنى القضائي، <r v=\"Acts.8.33\"></r><i>(السبعينية)</i>؛ خاصةً عن الدينونة الإلهية، <r v=\"John.3.19\"></r> <r v=\"John.5.24\"></r>، <r v=\"John.5.27\"></r>، <r v=\"John.5.29\"></r>، <r v=\"John.5.30\"></r> <r v=\"John.12.31\"></r> <r v=\"John.16.8\"></r>، <r v=\"John.16.11\"></r>، <r v=\"2Thess.1.5\"></r>، <r v=\"Heb.10.27\"></r>، <r v=\"Jas.2.13\"></r> <r v=\"Jas.5.12\"></r>، <r v=\"2Pet.2.4\"></r>، <r v=\"Rev.18.10\"></r>؛ في الجمع، <r v=\"Rev.16.7\"></r> <r v=\"Rev.19.2\"></r>؛ عن الدينونة الأخيرة، <r v=\"Matt.10.15\"></r> <r v=\"Matt.11.22\"></r>، <r v=\"Matt.11.24\"></r> <r v=\"Matt.12.36\"></r>، <r v=\"Matt.12.41\"></r>، <r v=\"Matt.12.42\"></r>، <r v=\"Luke.10.14\"></r> <r v=\"Luke.11.31\"></r>، <r v=\"Luke.11.32\"></r>، <r v=\"Heb.9.27\"></r>، <r v=\"2Pet.2.9\"></r> <r v=\"2Pet.3.7\"></r>، <r v=\"1John.4.17\"></r>، <r v=\"Jude.1.6\"></r>، <r v=\"Jude.1.15\"></r>؛ <g>ἡ κ. τῆς γεέννης</g>، <r v=\"Matt.23.33\"></r>.</s> <s n=\"3.\">بالكناية (كما في السبعينية ترجمةً لـ <h n=\"H4941\">מִשְׁפָּט</h>، <r v=\"Isa.5.7\"></r>، وفي مواضع أخرى؛ و<h n=\"H1779\">דִּינָא</h>، <r v=\"Dan.7.10\"></r>)، عن معيار الحكم: <b>حق</b>، <b>عدل</b>: <r v=\"Matt.12.18\"></r>، <r v=\"Matt.12.20\"></r> (السبعينية، <r v=\"Isa.42.43\"></r>) <r v=\"Matt.23.23\"></r>، <r v=\"Luke.11.42\"></r>؛ عن المحكمة (محكمة محلية)، <r v=\"Matt.5.21\"></r>، <r v=\"Matt.5.22\"></r>.†</s>","en":"<f><o>κρίσις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>κρίνω</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H4941\">מִשְׁפָּט</h>, also for <h n=\"H7379\">רִיב</h>, etc.;]</e> </et> <s n=\"1.\"><b>a seperating</b>, <b>selection</b> (Arist., al.)</s> <s n=\"2.\"><b>a decision</b>, <b>judgment</b> (cl.): <r v=\"John.8.16\"></r>, <r v=\"1Tim.5.24\"></r>, <r v=\"2Pet.2.11\"></r>, <r v=\"Jude.1.9\"></r>; <g>κ. κρίνειν</g>, <r v=\"John.7.24\"></r>; in forensic sense, <r v=\"Acts.8.33\"></r><i>(LXX)</i> (v. Page, in l.); esp. of the Divine judgment, <r v=\"John.3.19\"></r> <r v=\"John.5.24\"></r>, <r v=\"John.5.27\"></r>, <r v=\"John.5.29\"></r>, <r v=\"John.5.30\"></r> <r v=\"John.12.31\"></r> <r v=\"John.16.8\"></r>, <r v=\"John.16.11\"></r>, <r v=\"2Thess.1.5\"></r>, <r v=\"Heb.10.27\"></r>, <r v=\"Jas.2.13\"></r> <r v=\"Jas.5.12\"></r>, <r v=\"2Pet.2.4\"></r>, <r v=\"Rev.18.10\"></r>; pl., <r v=\"Rev.16.7\"></r> <r v=\"Rev.19.2\"></r>; of the last judgment, <r v=\"Matt.10.15\"></r> <r v=\"Matt.11.22\"></r>, <r v=\"Matt.11.24\"></r> <r v=\"Matt.12.36\"></r>, <r v=\"Matt.12.41\"></r>, <r v=\"Matt.12.42\"></r>, <r v=\"Luke.10.14\"></r> <r v=\"Luke.11.31\"></r>, <r v=\"Luke.11.32\"></r>, <r v=\"Heb.9.27\"></r>, <r v=\"2Pet.2.9\"></r> <r v=\"2Pet.3.7\"></r>, <r v=\"1John.4.17\"></r>, <r v=\"Jude.1.6\"></r>, <r v=\"Jude.1.15\"></r>; <g>ἡ κ. τῆς γεέννης</g>, <r v=\"Matt.23.33\"></r>.</s> <s n=\"3.\">By meton. (as in LXX for <h n=\"H4941\">מִשְׁפָּט</h>, <r v=\"Isa.5.7\"></r>, al.; <h n=\"H1779\">דִּינָא</h>, <r v=\"Dan.7.10\"></r>), of the standard of judgment, <b>right</b>, <b>justice</b>: <r v=\"Matt.12.18\"></r>, <r v=\"Matt.12.20\"></r> (LXX, <r v=\"Isa.42.43\"></r>) <r v=\"Matt.23.23\"></r>, <r v=\"Luke.11.42\"></r>; of the tribunal (a local court), <r v=\"Matt.5.21\"></r>, <r v=\"Matt.5.22\"></r>.†</s>"},"G2960":{"l":"κυριακός","o":2,"ar":"<f>**† <o>κυριακός</o>، <g>-ή, -όν</g></f> <s n=\"1.\">في النقوش كثيرًا: <b>خاص بالسيد</b> أو <b>المالك</b>، <b>إمبراطوري</b>.</s> <s n=\"2.\"><b>خاص بالرب</b> (أي المسيح): <g>δεῖπνον</g> (عشاء الرب)، <r v=\"1Cor.11.20\"></r>؛ <g>ἡμέρα</g> (يوم الرب)، <r v=\"Rev.1.10\"></r>.†</s>","en":"<f>**† <o>κυριακός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>κύριος</g>),</e> <e t=\"septuagint\">[in LXX: <g>κ. φωνή</g> (<g>Συριακή φ.</g>, R), <r v=\"2Macc.15.36\"></r> A*;]</e> </et> <s n=\"1.\">as freq. in Inscr. (LS, s.v.; Deiss., <i>BS</i>, 217 f.), of <b>the lord</b> or <b>master</b>, <b>imperial</b>.</s> <s n=\"2.\"><b>of the Lord</b> (i.e. Christ): <g>δεῖπνον</g>, <r v=\"1Cor.11.20\"></r>; <g>ἡμέρα</g>, <r v=\"Rev.1.10\"></r>. (Cf. <g>λόγια κ.</g>, Papias, Eus., <i>HE</i>, iii, 39, 1; <g>γραφαὶ κ.</g>, Clem. Alex., etc; for eccl. usage, cf. Soph., <i>Lex.</i>, s.v.)†</s>"},"G2941":{"l":"κυβέρνησις","o":1,"ar":"<f><o>κυβέρνησις</o>، <g>-εως, ἡ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>توجيه الدفة</b>، <b>قيادة السفينة</b>.</s> <s n=\"2.\">مجازيًا: <b>تدبير، قيادة</b>: في الجمع، <r v=\"1Cor.12.28\"></r>.†</s>","en":"<f><o>κυβέρνησις</o>, <g>-εως, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>κυβερνάω</g>, Lat. <l>gubernare</l>, <i>to guide</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Prov.1.5\"></r> <r v=\"Prov.11.14\"></r> <r v=\"Prov.24.6\"></r> (<h n=\"H8458\">תַּחְבֻּלוֹת</h>)*;]</e> </et> <s n=\"1.\"><b>steering</b>, <b>pilotage</b> (Plat.).</s> <s n=\"2.\">Metaph., <b>government</b>: pl., <r v=\"1Cor.12.28\"></r>.†</s>"},"G2994":{"l":"Λαοδικεύς","o":1,"ar":"<f><o>Λαοδικεύς</o>، <g>-έως, ὁ</g>،</f> <s><b>لاودكي</b>: <r v=\"Col.4.16\"></r>.†</s>","en":"<f><o>Λαοδικεύς</o>, <g>-έως, ὁ</g>,</f> <s><b>a Laodicean</b>: <r v=\"Col.4.16\"></r>.†</s>"},"G2944":{"l":"κυκλόω","o":4,"ar":"<f><o>κυκλόω</o>، <g>-ῶ</g></f> <s n=\"1.\"><b>دار في دائرة</b>، <b>دار حول</b>.</s> <s n=\"2.\"><b>أحاط</b>، <b>طوّق</b>: مع المنصوب للشخص، <r v=\"John.10.24\"></r>، <r v=\"Acts.14.20\"></r>؛ المبني للمجهول، <r v=\"Luke.21.20\"></r>، <r v=\"Heb.11.30\"></r> (قارن <g>περι-κυκλόω</g>).†</s>","en":"<f><o>κυκλόω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>κύκλος</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5437\">סבב</h>;]</e> </et> <s n=\"1.\"><b>to move in a circle</b>, <b>revolve</b>.</s> <s n=\"2.\"><b>to surround</b>, <b>encircle</b>: c. acc. pers., <r v=\"John.10.24\"></r> (WH, txt., cf. <g>-εύω</g>), <r v=\"Acts.14.20\"></r>; pass., <r v=\"Luke.21.20\"></r>, <r v=\"Heb.11.30\"></r> (cf. <g>περι-κυκλόω</g>).†</s>"},"G2959":{"l":"κυρία","o":2,"ar":"<f><o>κυρία</o></f> <s><b>سيدة</b>: <r v=\"2John.1.1\"></r>، <r v=\"2John.1.5\"></r>.†</s>","en":"<f><o>κυρία</o></f> <et> <e t=\"derivation\">(<g>Κυρία</g>, T, WH, mg.), <g>-ας, ἡ</g>,</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1404\">גְּבֶרֶת</h>;]</e> </et> <s><b>a lady</b>: <r v=\"2John.1.1\"></r>, <r v=\"2John.1.5\"></r> (on the interpretation, v. <i>ICC</i>, 167 ff.).†</s>"},"G2929":{"l":"κρυσταλλίζω","o":1,"ar":"<f>*† <o>κρυσταλλίζω</o></f> <s><b>لمع كالبلّور</b>، <b>كان صافيًا كالبلّور</b>: <r v=\"Rev.21.11\"></r> (<g>ἅπ. λεγ.</g>).†</s>","en":"<f>*† <o>κρυσταλλίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>κρύσταλλος</g>),</e> </et> <s><b>to shine like crystal</b>, <b>be crystal-clear</b>: <r v=\"Rev.21.11\"></r> (<g>ἅπ. λεγ.</g>).†</s>"},"G2900":{"l":"κραταιός","o":1,"ar":"<f><o>κραταιός</o>، <g>-ά, -όν</g></f> <s><b>قوي</b>، <b>قدير</b>: <r v=\"1Pet.5.6\"></r>.†</s>","en":"<f><o>κραταιός</o>, <g>-ά, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>κράτος</g>),</e> <e t=\"derivation\">(in cl. poët. form of <g>κρατερός</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H2388\">חָזָק</h> and cognates;]</e> </et> <s><b>strong</b>, <b>mighty</b>: <r v=\"1Pet.5.6\"></r>.†</s>"},"G2930":{"l":"κρύσταλλος","o":2,"ar":"<f><o>κρύσταλλος</o>، <g>-ου, ὁ</g></f> <s><b>بلّور</b>: <r v=\"Rev.4.6\"></r> <r v=\"Rev.22.1\"></r>.†</s>","en":"<f><o>κρύσταλλος</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>κρύος</g>, <i>frost</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Job.38.29\"></r>, <r v=\"Ps.147.6\"></r>, (<r v=\"Ps.147.17\"></r>), <r v=\"Ezek.1.22\"></r> (<h n=\"H7140\">קֶרַח</h>), etc.;]</e> </et> <s><b>crystal</b>: <r v=\"Rev.4.6\"></r> <r v=\"Rev.22.1\"></r>.†</s>"},"G2966":{"l":"κῶλον","o":1,"ar":"<f><o>κῶλον</o>، <g>-ου, τό</g>،</f> <s><b>عضو</b>، <b>طرف</b> من الجسد، <e t=\"septuagint\">[لكن في السبعينية (<r v=\"Lev.26.30\"></r>، <r v=\"Num.14.29\"></r>، <r v=\"Num.14.32\"></r>، <r v=\"Num.14.33\"></r>، <r v=\"1Sam.17.46\"></r>، <r v=\"Isa.66.24\"></r>*) ترجمةً لـ <h n=\"H6297\">פֶּגֶר</h>؛]</e> ومن ثم، <b>جثة</b>: <r v=\"Heb.3.17\"></r><i>(السبعينية)</i>.†</s>","en":"<f><o>κῶλον</o>, <g>-ου, τό</g>,</f> <s><b>a limb</b>, <b>member</b> of a body, <e t=\"septuagint\">[but in LXX (<r v=\"Lev.26.30\"></r>, <r v=\"Num.14.29\"></r>, <r v=\"Num.14.32\"></r>, <r v=\"Num.14.33\"></r>, <r v=\"1Sam.17.46\"></r>, <r v=\"Isa.66.24\"></r>*) for <h n=\"H6297\">פֶּגֶר</h>;]</e> hence, <b>carcase</b>: <r v=\"Heb.3.17\"></r><i>(LXX)</i>.†</s>"},"G2925":{"l":"κρούω","o":9,"ar":"<f><o>κρούω</o>،</f> <s><b>قرع</b>، <b>طرق</b>: على الباب، <r v=\"Matt.7.7\"></r>، <r v=\"Matt.7.8\"></r>، <r v=\"Luke.11.9\"></r>، <r v=\"Luke.11.10\"></r> <r v=\"Luke.12.36\"></r>، <r v=\"Acts.12.16\"></r>، <r v=\"Rev.3.20\"></r>؛ مع المنصوب، <g>τ. θύραν</g>، <r v=\"Luke.13.25\"></r>، <r v=\"Acts.12.13\"></r>.†</s>","en":"<f><o>κρούω</o>,</f> <et> <e t=\"septuagint\">[in LXX: seq. <g>ἐπί</g>, <r v=\"Judg.19.22\"></r>, <r v=\"Song.5.2\"></r> (<h n=\"H1849\">דִפק</h>);] c, acc., <g>τ. αὐλαίαν</g>, <r v=\"Jdt.14.14\"></r>*;]</e> </et> <s><b>to strike</b>, <b>knock</b>: at a door (<g>κόπτειν</g>, in Att.), <r v=\"Matt.7.7\"></r>, <r v=\"Matt.7.8\"></r>, <r v=\"Luke.11.9\"></r>, <r v=\"Luke.11.10\"></r> <r v=\"Luke.12.36\"></r>, <r v=\"Acts.12.16\"></r>, <r v=\"Rev.3.20\"></r>; c. acc., <g>τ. θύραν</g>, <r v=\"Luke.13.25\"></r>, <r v=\"Acts.12.13\"></r>.†</s>"},"G2946":{"l":"κύλισμα","o":1,"ar":"<f>**† <o>κύλισμα</o>، <g>-τος, τό</g></f> <s n=\"1.\"><b>لفّة</b>.</s> <s n=\"2.\">= <g>κυλισμός</g> (انظره)، <b>تدحرج</b>، <b>تمرّغ</b> (أو بمعنى <b>مكان التمرّغ</b>): <r v=\"2Pet.2.22\"></r>.†</s>","en":"<f>**† <o>κύλισμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>κυλίω</g>),</e> <e t=\"septuagint\">[in Sm.: <r v=\"Ezek.10.13\"></r>*;]</e> </et> <s n=\"1.\"><b>a roll</b>.</s> <s n=\"2.\">= <g>κυλισμός</g> (q.v.), <b>a rolling</b>, <b>wallowing</b> (or, as <g>κυλίστρα</g>, Xen., Eq., v. 3, <b>a rolling place</b>): <r v=\"2Pet.2.22\"></r> (Rec.).†</s>"},"G2943":{"l":"κυκλόθεν","o":3,"ar":"<f><o>κυκλόθεν</o>،</f> ظرف، <s><b>من كل جانب</b>، <b>حول</b>: <r v=\"Rev.4.3\"></r>، <r v=\"Rev.4.4\"></r>، <r v=\"Rev.4.8\"></r>.†</s>","en":"<f><o>κυκλόθεν</o>,</f> adv., <et> <e t=\"derivation\">(&lt; <g>κύκλος</g>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H5439\">מִסָּבִיב</h>, <h n=\"H5439\">סָבִיב</h>;]</e> </et> <s><b>from all sides</b>, <b>round about</b>: <r v=\"Rev.4.3\"></r>, <r v=\"Rev.4.4\"></r>, <r v=\"Rev.4.8\"></r>.†</s>"},"G2986":{"l":"λαμπρός","o":9,"ar":"<f>** <o>λαμπρός</o>، <g>-ά, -όν</g></f> <s><b>لامع</b>، <b>بهيّ</b>: <g>ποταμός</g>، <r v=\"Rev.22.1\"></r> (<g>ΕV</g>، <i>صافٍ</i>)؛ <g>ἀστήρ</g>، <r v=\"Rev.22.16\"></r>؛ عن الثياب، <b>لامع</b>، <b>فاخر</b>: <r v=\"Luke.23.11\"></r>، <r v=\"Acts.10.30\"></r>، <r v=\"Jas.2.2\"></r>، <r v=\"Jas.2.3\"></r>، <r v=\"Rev.15.6\"></r>، <r v=\"Rev.18.14\"></r>، <r v=\"Rev.19.8\"></r>.†</s>","en":"<f>** <o>λαμπρός</o>, <g>-ά, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>λάμπω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Tob.13.11\"></r>, <r v=\"Wis.6.12\"></r> <r v=\"Wis.17.20\"></r>, <r v=\"Sir.29.22\"></r> <r v=\"Sir.33.13\"></r> (<r v=\"Sir.30.25\"></r>) <r v=\"Sir.31.23\"></r>, <r v=\"EpJer.1.60\"></r>*;]</e> </et> <s><b>bright</b>, <b>brilliant</b>: <g>ποταμός</g>, <r v=\"Rev.22.1\"></r> (<g>ΕV</g>, <i>clear</i>); <g>ἀστήρ</g>, <r v=\"Rev.22.16\"></r>; of clothing, <b>brilliant</b>, <b>splendid</b>: <r v=\"Luke.23.11\"></r>, <r v=\"Acts.10.30\"></r>, <r v=\"Jas.2.2\"></r>, <r v=\"Jas.2.3\"></r>, <r v=\"Rev.15.6\"></r> <r v=\"Rev.18.14\"></r> <r v=\"Rev.19.8\"></r>.†</s>"},"G2990":{"l":"λανθάνω","o":6,"ar":"<f><o>λανθάνω</o>،</f> <s><b>خفي</b>، <b>استتر</b> (<b>عن</b>): <r v=\"Mark.7.24\"></r>، <r v=\"Luke.8.47\"></r>؛ مع المنصوب للشخص، <r v=\"Acts.26.26\"></r>، <r v=\"2Pet.3.5\"></r>، <r v=\"2Pet.3.8\"></r>؛ ويليه اسم الفاعل، <g>ἔλαθον ξενίσαντες</g>، <b>أضافوا وهم لا يدرون</b>، <r v=\"Heb.13.2\"></r> (قارن <g>ἐκ-</g>، <g>ἐπι-λανθάνω</g>).†</s>","en":"<f><o>λανθάνω</o>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H5956\">עלם</h> ni., etc.;]</e> </et> <s><b>to escape notice</b>, <b>be hidden</b> (<b>from</b>): <r v=\"Mark.7.24\"></r>, <r v=\"Luke.8.47\"></r>; c. acc. pers., <r v=\"Acts.26.26\"></r>, <r v=\"2Pet.3.5\"></r>, <r v=\"2Pet.3.8\"></r>; as in common cl. idiom, seq. ptcp., <g>ἔλαθον ξενίσαντες</g>, <b>entertained unawares</b>, <r v=\"Heb.13.2\"></r> (cf. <g>ἐκ-</g>, <g>ἐπι-λανθάνω</g>).†</s>"},"G2985":{"l":"λαμπάς","o":9,"ar":"<f><o>λαμπάς</o>، <g>-άδος, ἡ</g></f> <s><b>مشعل</b> (يُغذّى كثيرًا بالزيت كالسراج): <r v=\"Matt.25.1\"></r> وما يليه، <r v=\"John.18.3\"></r>، <r v=\"Acts.20.8\"></r>، <r v=\"Rev.4.5\"></r>، <r v=\"Rev.8.10\"></r>.†</s>","en":"<f><o>λαμπάς</o>, <g>-άδος, ἡ</g></f> <et> <e t=\"derivation\">(&lt; <g>λάμπω</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H3940\">לַפִּיד</h>;]</e> </et> <s><b>a torch</b> (freq. fed, like a lamp, with oil): <r v=\"Matt.25.1\"></r> ff., <r v=\"John.18.3\"></r>, <r v=\"Acts.20.8\"></r>, <r v=\"Rev.4.5\"></r> <r v=\"Rev.8.10\"></r>.†</s> <sy><i>SYN.</i>: <g>λύχος</g>, <i>lamp</i>, q.v.; <g>φανός</g>, <i>torch</i> or <i>lantern</i>; cf. Rutherford's <i>NPhr.</i>, 131 f.; Tr., <i>Syn.</i>, § xlvi; <i>DCG</i>, s.v. <i>lamp</i>; <i>DB</i>, iii, 43 f.</sy>"},"G2978":{"l":"λαῖλαψ","o":3,"ar":"<f><o>λαῖλαψ</o>، <g>-απος, ἡ</g>،</f> <s><b>نوء، إعصار</b>، <b>زوبعة</b>: <r v=\"Mark.4.37\"></r>، <r v=\"Luke.8.23\"></r>، <r v=\"2Pet.2.17\"></r>.†</s>","en":"<f><o>λαῖλαψ</o>, <g>-απος, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Job.21.18\"></r> <r v=\"Job.27.20\"></r> <h>א</h> (<h n=\"H5492\">סוּפָה</h>) <r v=\"Job.38.1\"></r>, <r v=\"Jer.25.32\"></r> (<h n=\"H5591\">סְעָרָה</h>, <h n=\"H5591\">סַעַר</h>), <r v=\"Wis.5.14\"></r>, <r v=\"Wis.5.23\"></r>, <r v=\"Sir.48.9\"></r>, <r v=\"Sir.48.12\"></r>*;]</e> </et> <s><b>a hurricane</b>, <b>whirlwind</b>: <r v=\"Mark.4.37\"></r>, <r v=\"Luke.8.23\"></r>, <r v=\"2Pet.2.17\"></r>.†</s> <sy><i>SYN.</i>: <g>θύελλα</g>, q.v., and cf. <g>ἄνεμος</g>.</sy>"},"G2915":{"l":"κριθή","o":1,"ar":"<f><o>κριθή</o>، <g>-ῆς, ἡ</g>،</f> <s><b>شعير</b>: في الجمع، <r v=\"Rev.6.6\"></r>.†</s>","en":"<f><o>κριθή</o>, <g>-ῆς, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H8184\">שְׂעֹרָה</h>;]</e> </et> <s><b>barley</b>: pl. (as usually in cl.), <r v=\"Rev.6.6\"></r>.†</s>"},"G2942":{"l":"κυβερνήτης","o":2,"ar":"<f><o>κυβερνήτης</o>، <g>-ου, ὁ</g></f> <s n=\"1.\"><b>رُبّان</b>، <b>مدبّر السفينة</b>: <r v=\"Acts.27.11\"></r>، <r v=\"Rev.18.17\"></r>.</s> <s n=\"2.\">في اليونانية الكلاسيكية: مجازيًا، <b>مرشد</b>، <b>حاكم</b>.†</s>","en":"<f><o>κυβερνήτης</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(v.s. <g>κυβέρνησις</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H2259\">חֹבֵל</h>, <r v=\"Ezek.27.8\"></r>, <r v=\"Ezek.27.27\"></r>, <r v=\"Ezek.27.28\"></r>, <r v=\"Prov.23.24\"></r>, <r v=\"4Macc.7.1\"></r>*;]</e> </et> <s n=\"1.\"><b>a steersman</b>, <b>pilot</b>: <r v=\"Acts.27.11\"></r>, <r v=\"Rev.18.17\"></r>.</s> <s n=\"2.\">Metaph., <b>a guide</b>, <b>governor</b> (Eur., Plat.).†</s>"},"G2949":{"l":"κῦμα","o":5,"ar":"<f><o>κῦμα</o>، <g>-τος, τό</g></f> <s><b>موجة</b>: في الجمع، <r v=\"Matt.8.24\"></r> <r v=\"Matt.14.24\"></r>، <r v=\"Mark.4.37\"></r>؛ <g>κ. θαλάσσης</g>، مجازيًا، <r v=\"Jude.1.13\"></r>.†</s>","en":"<f><o>κῦμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>κύω</g>, <i>to be pregnant</i>, <i>to swell</i>),</e> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1530\">גַּל</h>;]</e> </et> <s><b>a wave</b>: pl., <r v=\"Matt.8.24\"></r> <r v=\"Matt.14.24\"></r>, <r v=\"Mark.4.37\"></r>; <g>κ. θαλάσσης</g>, fig., <r v=\"Jude.1.13\"></r>.†</s> <sy><i>SYN.</i>: <g>κλύδων</g>, q.v.</sy>"},"G2939":{"l":"κτίστης","o":1,"ar":"<f><o>κτίστης</o>، <g>-ου, ὁ</g></f> <s n=\"1.\">في اليونانية الكلاسيكية: <b>مؤسِّس</b>.</s> <s n=\"2.\"><b>خالق</b>: عن الله، <r v=\"1Pet.4.19\"></r>.†</s>","en":"<f><o>κτίστης</o>, <g>-ου, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>κτίζω</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"2Sam.22.32\"></r> (Heb., al.), <r v=\"Jdt.9.12\"></r>, <r v=\"Sir.24.8\"></r>, II, IV Mac<i>5</i>*;]</e> </et> <s n=\"1.\">(cl.) <b>a founder</b>.</s> <s n=\"2.\"><b>a creator</b>: of God, <r v=\"1Pet.4.19\"></r>.†</s>"},"G2975":{"l":"λαγχάνω","o":4,"ar":"<f><o>λαγχάνω</o>،</f> <s n=\"1.\"><b>نال بالقرعة</b>، <b>نال، أصاب</b>: مع المصدر المعرَّف بالأداة، <r v=\"Luke.1.9\"></r>؛ مع منصوب الشيء، <r v=\"Acts.1.17\"></r>، <r v=\"2Pet.1.1\"></r>.</s> <s n=\"2.\"><b>ألقى قرعة، اقترع</b>: يليه <g>περί</g>، <r v=\"John.19.24\"></r>.</s>","en":"<f><o>λαγχάνω</o>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"1Sam.14.47\"></r> (<h n=\"H3920\">לכד</h>, v. Th., <i>Gr.</i>, 38), <r v=\"Wis.8.19\"></r>, <r v=\"3Macc.6.1\"></r>*;]</e> </et> <s n=\"1.\"><b>to obtain by lot</b>, <b>to obtain</b> (in cl., c. gen.): c. inf. art. (B1., § 36, 3; 71, 3), <r v=\"Luke.1.9\"></r>; c. acc. rei, <r v=\"Acts.1.17\"></r>, <r v=\"2Pet.1.1\"></r>.</s> <s n=\"2.\"><b>to draw lots</b>: seq. <g>περί</g>, <r v=\"John.19.24\"></r>.</s>"},"G2924":{"l":"κριτικός","o":1,"ar":"<f>* <o>κριτικός</o>، <g>-ή, -όν</g></f> <s><b>مُميِّز</b>، <b>قادر على التمييز</b> أو <b>الحكم</b>: مع المضاف إليه للمفعول، <r v=\"Heb.4.12\"></r>.†</s>","en":"<f>* <o>κριτικός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>κρίνω</g>),</e> </et> <s><b>critical</b>, <b>able to discern</b> or <b>judge</b>: c. gen. obj., <r v=\"Heb.4.12\"></r>.†</s>"},"G2926":{"l":"κρύπτη","o":1,"ar":"<f>*† <o>κρύπτη</o>، <g>-ης, ἡ</g>،</f> <s><b>سرداب</b>، <b>قبو</b>: <r v=\"Luke.11.33\"></r>.†</s>","en":"<f>*† <o>κρύπτη</o> (WH, R; <g>κρυπτή</g>, LT, Tr.; <g>-όν</g>, Rec.), <g>-ης, ἡ</g>,</f> <s><b>a crypt</b>, <b>cellar</b>: <r v=\"Luke.11.33\"></r>.†</s>"},"G2972":{"l":"Κῶς","o":null,"ar":"<f><o>Κῶς</o>، حالة الجر <g>Κῶ, ἡ</g>،</f> <s><b>كوس</b>، جزيرة في بحر إيجة: حالة النصب <g>Κῶ</g>، <r v=\"Acts.21.1\"></r>.†</s>","en":"<f><o>Κῶς</o>, gen. <g>Κῶ, ἡ</g>,</f> <s><b>Cos</b>, an island in the Ægean Sea: acc. <g>Κῶ</g>, <r v=\"Acts.21.1\"></r> (<g>Κῶν</g>, Rec.).†</s>"},"G2911":{"l":"κρημνός","o":3,"ar":"<f><o>κρημνός</o>، <g>-οῦ, ὁ</g></f> <s><b>جُرف، منحدر شديد</b>: <r v=\"Matt.8.32\"></r>، <r v=\"Mark.5.13\"></r>، <r v=\"Luke.8.33\"></r>.†</s>","en":"<f><o>κρημνός</o>, <g>-οῦ, ὁ</g></f> <et> <e t=\"derivation\">(&lt; <g>κρεμάννυμι</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"2Chr.25.12\"></r> (<h n=\"H5553\">סֶלַע</h>)*;]</e> </et> <s><b>a steep bank</b>: <r v=\"Matt.8.32\"></r>, <r v=\"Mark.5.13\"></r>, <r v=\"Luke.8.33\"></r>.†</s>"},"G2957":{"l":"Κυρήνη","o":1,"ar":"<f><o>Κυρήνη</o>، <g>-ης, ἡ</g>،</f> <s><b>القيروان</b>، مدينة في ليبية: <r v=\"Acts.2.10\"></r>.†</s>","en":"<f><o>Κυρήνη</o>, <g>-ης, ἡ</g>,</f> <s><b>Cyrene</b>, a city in Libya: <r v=\"Acts.2.10\"></r>.†</s>"},"G2982":{"l":"λαμά","o":2,"ar":"<f><o>λαμά</o> (العبرية <h n=\"H4100\">לָמָה</h>؛ وفي قراءة أخرى <g>λεμά</g> = الآرامية <h n=\"H3964\">לְמָא</h>)،</f> <s><b>لماذا</b>: <r v=\"Matt.27.46\"></r>، <r v=\"Mark.15.34\"></r>.†</s>","en":"<f><o>λαμά</o> (Heb. <h n=\"H4100\">לָמָה</h>, v.l. <g>λεμά</g> = Aram. <h n=\"H3964\">לְמָא</h>),</f> <s><b>why</b>: <r v=\"Matt.27.46\"></r> (WH, mg., <g>λεμά</g> TTr., WH, txt., <g>λεμά</g> L), <r v=\"Mark.15.34\"></r> (<g>λεμά</g> LT, <g>λαμμᾶ</g>, Rec.).†</s>"},"G2958":{"l":"Κυρήνιος","o":1,"ar":"<f><o>Κυρήνιος</o></f> <s><b>كيرينيوس</b>، وبالصواب <b>كويرينيوس</b>: <r v=\"Luke.2.2\"></r>.†</s>","en":"<f><o>Κυρήνιος</o></f> <et> <e t=\"derivation\">(prop. <g>-ίνιος</g>, v. Bl., 13; <g>-ῖνος</g> L, <g>-εῖνος</g>, Tr., WH, mg.), <g>-ου, ὁ</g>,</e> </et> <s><b>Quirinus</b>, prop. <b>Quirinius</b>: <r v=\"Luke.2.2\"></r>.†</s>"},"G2951":{"l":"κύμινον","o":1,"ar":"<f><o>κύμινον</o>، <g>-ου, τό</g>،</f> <s><b>كمّون</b>: <r v=\"Matt.23.23\"></r>.†</s>","en":"<f><o>κύμινον</o>, <g>-ου, τό</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Isa.28.25\"></r>, <r v=\"Isa.28.27\"></r> (<h n=\"H3646\">כַּמֹּן</h>)*;]</e> </et> <s><b>cummin</b>: <r v=\"Matt.23.23\"></r>.†</s>"},"G2991":{"l":"λαξευτός","o":1,"ar":"<f>† <o>λαξευτός</o>، <g>-ή, όν</g></f> <s><b>منحوت</b> (في الصخر)؛ <r v=\"Luke.23.53\"></r> (ويستعمل كتّاب <g>κοινή</g> في مواضع أخرى <g>λατομητός</g>، <r v=\"2Kgs.12.12\"></r>، وفي مواضع أخرى؛ قارن <g>λατομέω</g>).†</s>","en":"<f>† <o>λαξευτός</o>, <g>-ή, όν</g></f> <et> <e t=\"derivation\">(&lt; <g>λαξεύω</g>; &lt; <g>λᾶς</g>, <i>a stone</i>, <g>ξέω</g>, <i>to scrape</i>),</e> <e t=\"septuagint\">[in LXX: <r v=\"Deut.4.49\"></r> (<h n=\"H6449\">פִּסְגָּה</h>); in Aq.: <r v=\"Num.21.20\"></r>; Th.: <r v=\"Judg.7.11\"></r>*;]</e> </et> <s><b>hewn</b> (in stone); <r v=\"Luke.23.53\"></r> (elsewhere <g>κοινή</g> writers use <g>λατομητός</g>, <r v=\"2Kgs.12.12\"></r>, al.; cf. <g>λατομέω</g>).†</s>"},"G2988":{"l":"λαμπρῶς","o":10,"ar":"<f>* <o>λαμπρῶς</o>،</f> ظرف، <s><b>بترفّه، ببهاء</b>: عن الطعام الفاخر (كما يرد كثيرًا؛ قارن <g>ἐδέσματα</g> <g>λαμπρά</g>، <r v=\"Sir.29.22\"></r>)، <r v=\"Luke.16.19\"></r>.†</s>","en":"<f>* <o>λαμπρῶς</o>,</f> adv., <s><b>splendidly</b>: of sumptuous fare (as freq.; cf. <g>ἐδέσματα</g> <g>λαμπρά</g>, <r v=\"Sir.29.22\"></r>), <r v=\"Luke.16.19\"></r>.†</s>"},"G2952":{"l":"κυνάριον","o":4,"ar":"<f>* <o>κυνάριον</o>، <g>-ου, τό</g></f> <s><b>كلب صغير، جرو</b>: <r v=\"Matt.15.26\"></r>، <r v=\"Matt.15.27\"></r>، <r v=\"Mark.7.27\"></r>، <r v=\"Mark.7.28\"></r>.†</s>","en":"<f>* <o>κυνάριον</o>, <g>-ου, τό</g></f> <et> <e t=\"derivation\">(in Att. also <g>κυνίδιον</g>, dim. of <g>κύων</g>),</e> </et> <s><b>a little dog</b>: <r v=\"Matt.15.26\"></r>, <r v=\"Matt.15.27\"></r>, <r v=\"Mark.7.27\"></r>, <r v=\"Mark.7.28\"></r>.†</s>"},"G2984":{"l":"Λάμεχ","o":1,"ar":"<f><o>Λάμεχ</o>، <g>ὁ</g>، لا يُصرَّف (بالعبرية <h n=\"H3929\">לֶמֶךְ</h>)،</f> <s><b>لامك</b> (<r v=\"Gen.5.25\"></r>): <r v=\"Luke.3.36\"></r>.†</s>","en":"<f><o>Λάμεχ</o>, <g>ὁ</g>, indecl. (Heb. <h n=\"H3929\">לֶמֶךְ</h>),</f> <s><b>Lamech</b> (<r v=\"Gen.5.25\"></r>): <r v=\"Luke.3.36\"></r>.†</s>"},"G2974":{"l":"κωφός","o":14,"ar":"<f><o>κωφός</o>، <g>-ή, -όν</g></f> <s><b>كليل</b>، <b>بليد</b>. مجازيًا، عن الحواس، خاصةً <s n=\"(a)\">عن النطق، <b>أخرس</b>: <r v=\"Matt.9.32\"></r>، <r v=\"Matt.9.33\"></r>، <r v=\"Matt.12.22\"></r>، <r v=\"Matt.15.30\"></r>، <r v=\"Matt.15.31\"></r>، <r v=\"Luke.1.22\"></r>، <r v=\"Luke.11.14\"></r>؛</s> <s n=\"(b)\">عن السمع، <b>أصمّ</b>: <r v=\"Matt.11.5\"></r>، <r v=\"Mark.7.32\"></r>، <r v=\"Mark.7.37\"></r>، <r v=\"Mark.9.25\"></r>، <r v=\"Luke.7.22\"></r>.†</s> </s>","en":"<f><o>κωφός</o>, <g>-ή, -όν</g></f> <et> <e t=\"derivation\">(&lt; <g>κόπτω</g>),</e> <e t=\"septuagint\">[in LXX chiefly (<r v=\"Exod.4.11\"></r>, al.) for <h n=\"H483\">אִלֵּם</h>; for <h n=\"H2796\">חֵרֵשׁ</h>, <r v=\"Hab.2.18\"></r>;]</e> </et> <s><b>blunt</b>, <b>dull</b>. Metaph., of the senses, esp. <s n=\"(a)\">of speech, <b>dumb</b>: <r v=\"Matt.9.32\"></r>, <r v=\"Matt.9.33\"></r> <r v=\"Matt.12.22\"></r> <r v=\"Matt.15.30\"></r>, <r v=\"Matt.15.31\"></r>, <r v=\"Luke.1.22\"></r> <r v=\"Luke.11.14\"></r>;</s> <s n=\"(b)\">of hearing, <b>deaf</b>: <r v=\"Matt.11.5\"></r>, <r v=\"Mark.7.32\"></r>, <r v=\"Mark.7.37\"></r> <r v=\"Mark.9.25\"></r>, <r v=\"Luke.7.22\"></r>.†</s> </s>"},"G2933":{"l":"κτῆμα","o":4,"ar":"<f><o>κτῆμα</o>، <g>-τος, τό</g></f> <s><b>مُقتنى</b>، <b>ملك، أموال</b>: <r v=\"Matt.19.22\"></r>، <r v=\"Mark.10.22\"></r>، <r v=\"Acts.2.45\"></r>، <r v=\"Acts.5.1\"></r>.†</s>","en":"<f><o>κτῆμα</o>, <g>-τος, τό</g></f> <et> <e t=\"derivation\">(&lt; <g>κτάομαι</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H3754\">כֶּרֶם</h>, etc.;]</e> </et> <s><b>a possession</b>, <b>property</b>: <r v=\"Matt.19.22\"></r>, <r v=\"Mark.10.22\"></r>, <r v=\"Acts.2.45\"></r> <r v=\"Acts.5.1\"></r>.†</s>"},"G2969":{"l":"κωμόπολις","o":1,"ar":"<f>*† <o>κωμόπολις</o>، <g>-εως, ἡ</g>،</f> <s><b>بلدة ريفية</b>: <r v=\"Mark.1.38\"></r>.†</s>","en":"<f>*† <o>κωμόπολις</o>, <g>-εως, ἡ</g>,</f> <s><b>a country town</b>: <r v=\"Mark.1.38\"></r> (v. Swete, in l.).†</s>"},"G2903":{"l":"κράτιστος","o":4,"ar":"<f><o>κράτιστος</o>، <g>-η, -ον</g>،</f> <e t=\"derivation\">صيغة التفضيل العليا من <g>κρατύς</g>،</e> <s n=\"1.\">في اليونانية الكلاسيكية: <b>الأقوى</b>، <b>الأشد بأسًا</b>.</s> <s n=\"2.\"><b>الأنبل</b>، <b>الأفضل</b> (قارن <g>κρείσσων</g>)، <b>الفائق الاحترام (العزيز)</b>: في النداء، <g>κρατίστε</g>، لقبًا للتكريم والاحترام، <r v=\"Luke.1.3\"></r>، <r v=\"Acts.23.26\"></r> <r v=\"Acts.24.3\"></r> <r v=\"Acts.26.25\"></r>.†</s>","en":"<f><o>κράτιστος</o>, <g>-η, -ον</g>,</f> <e t=\"derivation\">superl. of <g>κρατύς</g> (Hom.),</e> <s n=\"1.\"><b>strongest</b>, <b>mightiest</b> (Hom.).</s> <s n=\"2.\"><b>noblest</b>, <b>best</b> (cf. <g>κρείσσων</g>), <b>most excellent</b> (Pind., Soph., al.): voc., <g>κρατίστε</g>, as title of honour and respect (<i>DCG</i>, ii, 727<i>a</i>), <r v=\"Luke.1.3\"></r>, <r v=\"Acts.23.26\"></r> <r v=\"Acts.24.3\"></r> <r v=\"Acts.26.25\"></r>.†</s>"},"G2976":{"l":"Λάζαρος","o":15,"ar":"<f><o>Λάζαρος</o>، <g>-ου, ὁ</g>،</f> <s>اختصار عامّي لـ <g>Ἐλεαζάρ</g> (<g>άζαρος</g>، انظره)، <b>لعازر</b>؛ <s n=\"1.\">من بيت عنيا: <r v=\"John.11.1\"></r> وما يليه، <r v=\"John.12.1\"></r>، <r v=\"John.12.2\"></r>، <r v=\"John.12.9\"></r>، <r v=\"John.12.10\"></r>، <r v=\"John.12.17\"></r>.</s> <s n=\"2.\">المسكين في المثل: <r v=\"Luke.16.20\"></r>، <r v=\"Luke.16.23-Luke.16.25\"></r>.†</s> </s>","en":"<f><o>Λάζαρος</o>, <g>-ου, ὁ</g>,</f> <s>colloquial abbreviation of <g>Ἐλεαζάρ</g> (<g>άζαρος</g>), q.v.), <b>Lazarus</b>; <s n=\"1.\">of Bethany: <r v=\"John.11.1\"></r> ff. <r v=\"John.12.1\"></r>, <r v=\"John.12.2\"></r>, <r v=\"John.12.9\"></r>, <r v=\"John.12.10\"></r>, <r v=\"John.12.17\"></r>.</s> <s n=\"2.\">The beggar in the parable: <r v=\"Luke.16.20\"></r>, <r v=\"Luke.16.23-Luke.16.25\"></r>.†</s> </s>"},"G2977":{"l":"λάθρᾳ","o":4,"ar":"<f><o>λάθρᾳ</o>،</f> ظرف، <s><b>سرًّا، خفيةً</b>: <r v=\"Matt.1.19\"></r> <r v=\"Matt.2.7\"></r>، <r v=\"Mark.5.33\"></r>، <r v=\"John.11.28\"></r>، <r v=\"Acts.16.37\"></r>.†</s>","en":"<f><o>λάθρᾳ</o> (Att.; in Hom., <g>-ρῃ</g>, Rec. <g>-ρα</g>),</f> adv., <et> <e t=\"septuagint\">[in LXX chiefly for ‎<h n=\"H5643\">בַּסֵּתֶר</h>;]</e> </et> <s><b>secretly</b>: <r v=\"Matt.1.19\"></r> <r v=\"Matt.2.7\"></r>, <r v=\"Mark.5.33\"></r> (WH, mg.), <r v=\"John.11.28\"></r>, <r v=\"Acts.16.37\"></r>.†</s>"},"G2954":{"l":"Κύπρος","o":5,"ar":"<f><o>Κύπρος</o>، <g>-ου, ἡ</g>،</f> <s><b>قبرس</b>: <r v=\"Acts.11.19\"></r> <r v=\"Acts.13.4\"></r> <r v=\"Acts.15.39\"></r> <r v=\"Acts.21.3\"></r> <r v=\"Acts.27.4\"></r>.†</s>","en":"<f><o>Κύπρος</o>, <g>-ου, ἡ</g>,</f> <s><b>Cyprus</b>: <r v=\"Acts.11.19\"></r> <r v=\"Acts.13.4\"></r> <r v=\"Acts.15.39\"></r> <r v=\"Acts.21.3\"></r> <r v=\"Acts.27.4\"></r>.†</s>"},"G2973":{"l":"Κωσάμ","o":1,"ar":"<f><o>Κωσάμ</o>، <g>ὁ</g>،</f> <s><b>قصم</b>: <r v=\"Luke.3.28\"></r>.†</s>","en":"<f><o>Κωσάμ</o>, <g>ὁ</g>,</f> <s><b>Cosam</b>: <r v=\"Luke.3.28\"></r>.†</s>"},"G2997":{"l":"λάσκω","o":null,"ar":"<f>* <o>λάσκω</o>،</f> <s n=\"1.\">(في الكلاسيكية، شعرًا) <b>رنّ</b>، <b>تحطّم بصوت</b>، <b>تشقّق</b>؛ وفي النثر المتأخر، <b>انشقّ</b> أو <b>انفجر بصوت</b>: <r v=\"Acts.1.18\"></r> (<g>ἐλάκησεν</g>، وربما هي من <g>λακέω</g>، انظره).</s> <s n=\"2.\">(في الكلاسيكية، نثرًا) <b>صرخ</b>، <b>صاح</b>.†</s>","en":"<f>* <o>λάσκω</o>,</f> <s n=\"1.\">(in cl., poët.) <b>to clang</b>, <b>crash</b>, <b>crack</b>; in late prose, <b>to crack</b> or <b>burst noisily</b>: <r v=\"Acts.1.18\"></r> (<g>ἐλάκησεν</g>, perh., however, from <g>λακέω</g>, q.v.; Bl., in l.).</s> <s n=\"2.\">(in cl., prose) <b>to scream</b>, <b>shout</b>.†</s>"},"G2981":{"l":"λαλία","o":3,"ar":"<f><o>λαλία</o>، <g>-ᾶς, ἡ</g>،</f> <s n=\"1.\"><b>ثرثرة</b>.</s> <s n=\"2.\"><b>كلام</b>، <b>لهجة</b>، <b>حديث</b>: <r v=\"Matt.26.73\"></r> (قارن <r v=\"Song.4.3\"></r>)، <r v=\"John.4.42\"></r> <r v=\"John.8.43\"></r>.†</s>","en":"<f><o>λαλία</o>, <g>-ᾶς, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H1697\">דָּבָר</h>, <h n=\"H1700\">דִּבְרָה</h>;]</e> </et> <s n=\"1.\"><b>loquacity</b>.</s> <s n=\"2.\"><b>talk</b>, <b>speech</b>, <b>conversation</b>: <r v=\"Matt.26.73\"></r> (cf. <r v=\"Song.4.3\"></r>), <r v=\"John.4.42\"></r> <r v=\"John.8.43\"></r>.†</s>"},"G2996":{"l":"Λασέα","o":1,"ar":"<f><o>Λασέα</o>، <g>-ας, ἡ</g>،</f> <s><b>لسائية</b>، مدينة في كريت، غير معروفة من مصادر أخرى: <r v=\"Acts.27.8\"></r>.†</s>","en":"<f><o>Λασέα</o> (Rec. <g>-αία</g>), <g>-ας, ἡ</g>,</f> <s><b>Lasea</b>, a city of Crete, otherwise unknown: <r v=\"Acts.27.8\"></r>.†</s>"},"G2916":{"l":"κρίθινος","o":2,"ar":"<f><o>κρίθινος</o>، <g>-η, -ον</g></f> <s><b>من الشعير</b>: <r v=\"John.6.9\"></r>، <r v=\"John.6.13\"></r>.</s>","en":"<f><o>κρίθινος</o>, <g>-η, -ον</g></f> <et> <e t=\"derivation\">(&lt; <g>κριθή</g>),</e> <e t=\"septuagint\">[in LXX for <h n=\"H8184\">שְׂעֹרָה</h>;]</e> </et> <s><b>of barley</b>: <r v=\"John.6.9\"></r>, <r v=\"John.6.13\"></r>.</s>"},"G2918":{"l":"κρίνον","o":2,"ar":"<f><o>κρίνον</o>، <g>-ου, τό</g></f> <s><b>زنبقة</b>: <r v=\"Matt.6.28\"></r>، <r v=\"Luke.12.27\"></r>.†</s>","en":"<f><o>κρίνον</o>, <g>-ου, τό</g></f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H7799\">שׁוּשַׁן</h>, <h n=\"H7799\">שׁוֹשַׁנָּה</h>;]</e> </et> <s><b>a lily</b>: <r v=\"Matt.6.28\"></r>, <r v=\"Luke.12.27\"></r>.†</s>"},"G2971":{"l":"κώνωψ","o":1,"ar":"<f>* <o>κώνωψ</o>، <g>-ωπος, ὁ</g>،</f> <s><b>بعوضة</b>: <r v=\"Matt.23.24\"></r>.†</s>","en":"<f>* <o>κώνωψ</o>, <g>-ωπος, ὁ</g>,</f> <s><b>a gnat</b>: <r v=\"Matt.23.24\"></r>.†</s>"},"G2979":{"l":"λακτίζω","o":1,"ar":"<f>* <o>λακτίζω</o></f> <s><b>رفس</b>: <r v=\"Acts.26.14\"></r>.†</s>","en":"<f>* <o>λακτίζω</o></f> <et> <e t=\"derivation\">(&lt; <g>λάξ</g>, <i>with the foot</i>),</e> </et> <s><b>to kick</b>: <r v=\"Acts.26.14\"></r>.†</s>"},"G2948":{"l":"κυλλός","o":4,"ar":"<f>* <o>κυλλός</o>، <g>-ή, -όν</g>،</f> <s n=\"1.\"><b>أعوج</b>، <b>أشلّ</b>: <r v=\"Matt.15.30\"></r>، <r v=\"Matt.15.31\"></r>؛</s> <s n=\"2.\"><b>أقطع (مبتور العضو)</b>: <r v=\"Matt.18.8\"></r>، <r v=\"Mark.9.43\"></r>.†</s>","en":"<f>* <o>κυλλός</o>, <g>-ή, -όν</g>,</f> <s n=\"1.\"><b>crooked</b>, <b>crippled</b>: <r v=\"Matt.15.30\"></r>, <r v=\"Matt.15.31\"></r> (WH, txt. om.);</s> <s n=\"2.\"><b>maimed</b>: <r v=\"Matt.18.8\"></r>, <r v=\"Mark.9.43\"></r>.†</s>"},"G2955":{"l":"κύπτω","o":3,"ar":"<f><o>κύπτω</o>،</f> <s><b>حنى رأسه</b>، <b>انحنى</b>: <r v=\"Mark.1.7\"></r>؛ يليه <g>κάτω</g>، <r v=\"John.8.6\"></r>، <r v=\"John.8.8\"></r> (قارن <g>ἀνα-</g>، <g>παρα-</g>، <g>συν-κύπτω</g>).†</s>","en":"<f><o>κύπτω</o>,</f> <et> <e t=\"septuagint\">[in LXX chiefly for <h n=\"H6915\">קדד</h>;]</e> </et> <s><b>to bow the head</b>, <b>stoop down</b>: <r v=\"Mark.1.7\"></r>; seq. <g>κάτω</g>, <r v=\"John.8.6\"></r>, <r v=\"John.8.8\"></r> (cf. <g>ἀνα-</g>, <g>παρα-</g>, <g>συν-κύπτω</g>).†</s>"},"G2953":{"l":"Κύπριος","o":3,"ar":"<f><o>Κύπριος</o>، <g>-α, -ον</g>،</f> <s><b>من قبرس</b>، <b>قبرسي</b>: <r v=\"Acts.4.36\"></r> <r v=\"Acts.11.20\"></r> <r v=\"Acts.21.16\"></r>.†</s>","en":"<f><o>Κύπριος</o>, <g>-α, -ον</g>,</f> <s><b>of Cyprus</b>, <b>Cyprian</b>: <r v=\"Acts.4.36\"></r> <r v=\"Acts.11.20\"></r> <r v=\"Acts.21.16\"></r>.†</s>"},"G2998":{"l":"λατομέω","o":2,"ar":"<f>† <o>λατομέω</o>، <g>-ῶ</g></f> <s><b>نحت</b>، <b>نقر</b> الحجارة: <r v=\"Matt.27.60\"></r>، <r v=\"Mark.15.46\"></r>.†</s>","en":"<f>† <o>λατομέω</o>, <g>-ῶ</g></f> <et> <e t=\"derivation\">(&lt; <g>λατόμος</g>, <i>a stonecutter</i>, <r v=\"2Kgs.12.12\"></r>, al.; &lt; <g>λᾶς</g>, <g>τέμνω</g>; cf. <g>λαξευτός</g>),</e> <e t=\"septuagint\">[in LXX: <r v=\"1Chr.22.2\"></r>, al. (<h n=\"H2672\">חצב</h>); <r v=\"Exod.21.33\"></r>, Num_21:18 (<h n=\"H3738\">כּרה</h>);]</e> </et> <s><b>to hew</b>, <b>hew out</b> stones: <r v=\"Matt.27.60\"></r>, <r v=\"Mark.15.46\"></r>.†</s>"},"G2905":{"l":"κραυγάζω","o":9,"ar":"<f><o>κραυγάζω</o> (مشتقة من <g>κραυγή</g>)،</f> <s n=\"1.\">عن الحيوانات، <b>نبح</b>، <b>نعق</b>، إلخ.</s> <s n=\"2.\">عن البشر، <b>صرخ</b>، <b>صاح</b>: <r v=\"Matt.12.19\"></r>، <r v=\"John.12.13\"></r>، <r v=\"John.19.15\"></r>، <r v=\"Acts.22.23\"></r>؛ يليه <g>λέγων</g>، <r v=\"John.18.40\"></r>، <r v=\"John.19.6\"></r>، <r v=\"John.19.12\"></r>؛ <g>καὶ λέγων</g>، <r v=\"Luke.4.41\"></r>؛ <g>φωνῇ μεγάλῃ</g>، <r v=\"John.11.43\"></r>.†</s>","en":"<f><o>κραυγάζω</o> (&lt; <g>κραυγή</g>),</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Ezra.3.13\"></r> (<h n=\"H7321\">רוּעַ</h> hi.)*;]</e> = <g>κράζω</g>,</et> <s n=\"1.\">of animals, <b>to bay</b>, <b>to croak</b>, etc.</s> <s n=\"2.\">Of men, <b>to cry out</b>, <b>shout</b>: <r v=\"Matt.12.19\"></r>, <r v=\"John.12.13\"></r> <r v=\"John.19.15\"></r>, <r v=\"Acts.22.23\"></r>; seq. <g>λέγων</g>, <r v=\"John.18.40\"></r> <r v=\"John.19.6\"></r>, <r v=\"John.19.12\"></r>; <g>καὶ λέγων</g>, <r v=\"Luke.4.41\"></r> (WH, <g>κράζ -</g>); <g>φωνῇ μεγάλῃ</g>, <r v=\"John.11.43\"></r> (cf. Abbott, <i>JV</i>, 269 f.).†</s>"},"G2968":{"l":"κώμη","o":28,"ar":"<f><o>κώμη</o>، <g>-ης, ἡ</g>،</f> <s><b>قرية</b> أو <b>بلدة ريفية</b>، أصلاً في مقابل المدينة المسوَّرة: <r v=\"Matt.14.15\"></r>، <r v=\"Mark.6.6\"></r>، وفي مواضع أخرى؛ <g>πόλεις καὶ κ.</g>، <r v=\"Matt.9.35\"></r>، وفي مواضع أخرى؛ مع ذكر الاسم، <g>Βηθλεέμ</g>، <r v=\"John.7.42\"></r>؛ <g>Βηθανΐα</g>، <r v=\"John.11.1\"></r>؛ مع اسم المنطقة، <g>τὰς κ. Καισαρίας</g>، <r v=\"Mark.8.27\"></r>؛ <g>Σαμαρειτῶν</g>، <r v=\"Luke.9.52\"></r>، <r v=\"Acts.8.25\"></r>.</s>","en":"<f><o>κώμη</o>, <g>-ης, ἡ</g>,</f> <et> <e t=\"septuagint\">[in LXX for <h n=\"H1323\">בַּת</h>, <h n=\"H2691\">חָצֵר</h>, <h n=\"H5892\">עִיר</h>, etc.;]</e> </et> <s><b>a village</b> or <b>country town</b>, prop, as opp. to a walled city: <r v=\"Matt.14.15\"></r>, <r v=\"Mark.6.6\"></r>, al.; <g>πόλεις καὶ κ.</g>, <r v=\"Matt.9.35\"></r>, al.; with the name added, <g>Βηθλεέμ</g>, <r v=\"John.7.42\"></r>; <g>Βηθανΐα</g>, <r v=\"John.11.1\"></r>; with the name of the district, <g>τὰς κ. Καισαρίας</g>, <r v=\"Mark.8.27\"></r>; <g>Σαμαρειτῶν</g>, <r v=\"Luke.9.52\"></r>, <r v=\"Acts.8.25\"></r>.</s>"},"G2956":{"l":"Κυρηναῖος","o":6,"ar":"<f><o>Κυρηναῖος</o>، <g>-α, -ον</g></f> <s><b>من القيروان</b>، <b>قيرواني</b>: <r v=\"Matt.27.32\"></r>، <r v=\"Mark.15.21\"></r>، <r v=\"Luke.23.26\"></r>، <r v=\"Acts.6.9\"></r>، <r v=\"Acts.11.20\"></r>، <r v=\"Acts.13.1\"></r>.†</s>","en":"<f><o>Κυρηναῖος</o>, <g>-α, -ον</g></f> <et> <e t=\"derivation\">(&lt; <g>Κυρήνη</g>),</e> </et> <s><b>of Cyrene</b>, <b>a Cyrenæan</b>: <r v=\"Matt.27.32\"></r>, <r v=\"Mark.15.21\"></r>, <r v=\"Luke.23.26\"></r>, <r v=\"Acts.6.9\"></r> <r v=\"Acts.11.20\"></r> <r v=\"Acts.13.1\"></r>.†</s>"},"G2947":{"l":"κυλίω","o":1,"ar":"<f><o>κυλίω</o> صيغة متأخرة من <g>κυλίνδω</g>،</f> <s><b>دحرج</b>، <b>دحرج قُدُمًا</b>. المبني للمجهول، <b>تدحرج</b>؛ وعن الأشخاص، <b>تمرّغ</b>: <r v=\"Mark.9.20\"></r>.†</s>","en":"<f><o>κυλίω</o> late form of <g>κυλίνδω</g>,</f> <et> <e t=\"septuagint\">[in LXX: <r v=\"Josh.10.18\"></r>, <r v=\"1Sam.14.33\"></r>, al. (<h n=\"H1556\">גּלל</h>), <r v=\"2Kgs.9.33\"></r> (<h n=\"H8058\">שׁמט</h>), al.;]</e> </et> <s><b>to roll</b>, <b>roll along</b>. Pass., <b>to be rolled</b>; of persons (in Hom, as sign of grief), <b>to roll</b> or <b>wallow</b>: <r v=\"Mark.9.20\"></r>.†</s>"}});A.got[29]=1})(window.ABBOTT=window.ABBOTT||{D:{},got:{}});